var PH_MAP = {};
// te emotki mają własne grafiki 8-bit (emo8.js) – nie zamieniamy ich na ikony Phosphor
for (const k of ['🥚', '🪺', '☕', '📚', '🃏', '🏠', '👥', '📅', '🗓', '✏', '📝', '🗑', '📷', '🎁', '🏆', '🔒', '🔓', '🎲', '⚔', '🎯', '🛡', '🔥', '⚡', '✨', '⭐', '🧪', '🧠', '🔮', '⏱', '⏳', '🎓', '🎉', '💎']) delete PH_MAP[k];
var phSVG = (name, cls = '') => `<svg class="ph ${cls}" viewBox="0 0 256 256" aria-hidden="true"><use href="#ph-${name}"/></svg>`;
(function phSprite() {
  const s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  s.setAttribute('style', 'display:none'); s.setAttribute('aria-hidden', 'true');
  s.innerHTML = Object.entries(PH_PATHS).map(([n, p]) => `<symbol id="ph-${n}" viewBox="0 0 256 256">${p}</symbol>`).join('');
  document.body.prepend(s);
})();
var PH_SEL = '#tabs a > span, .hubnav a > span, .sc > span, .mtile > span, h1, h2, h3, summary, summary > b, .studybar .title, button, .seg button, .banner > span, .card > b, label > span > b, .row > b.grow';
var PH_SKIP = '.dbag, .dloot, .cls-tabs, .mc-bar, .hint-dot, .hintbox, .hint-chip, #gc-fab, #gc-panel, .runes, .ev-chest, .bless, .badge-st, .stk, .st-row, .stbar, .tile, .inv-st, .chat-st, .mini-st, .egg-pick, .egg-hatch, .egg-nest, .egg-cal, .egg-wrap, .drop-ic, .big-st, .ci, .av, .av-big, .sh-av, .avimg, .avemoji, .pp-av, .pp-emojis, .emoji-big, .emo-row, .emo, .rx-thumb, .rx-default, .rx-card, .gift-pick, .cpick, .sh-pickbar, .medal, .reveal, .stfly, .msg, .fc3d, .face, .celebrate, [data-noic], [contenteditable]';
var PH_RE = /^(\s*)((?:\p{Extended_Pictographic}|[\u2190-\u21FF\u2300-\u23FF\u2B00-\u2BFF])(?:\uFE0F|\u200D\p{Extended_Pictographic})*)\s*/u;
var phOn = () => !(typeof S !== 'undefined' && S?.settings?.emojiIcons === false);
// wyłączone w ustawieniach: przywracamy oryginalne emotki (np. w dolnym pasku, który się nie przerysowuje)
function phUndo() {
  for (const el of document.querySelectorAll('[data-ic]')) {
    const svg = el.querySelector(':scope > svg.ph');
    if (svg && el.dataset.ic.length > 1) svg.replaceWith(el.dataset.ic.slice(1) + (svg.classList.contains('lead') ? ' ' : ''));
    delete el.dataset.ic;
  }
}
function phDecorate(root = document) {
  if (!phOn()) return phUndo();
  const els = root.querySelectorAll ? root.querySelectorAll(PH_SEL) : [];
  for (const el of els) {
    if (el.dataset.ic || el.closest(PH_SKIP)) continue;
    el.dataset.ic = '-';
    let t = el.firstChild;
    while (t && t.nodeType === 3 && !t.nodeValue.trim()) t = t.nextSibling;
    if (!t || t.nodeType !== 3) continue;
    const m = t.nodeValue.match(PH_RE); if (!m) continue;
    const name = PH_MAP[m[2].replace(/\uFE0F/g, '')]; if (!name) continue;
    const rest = t.nodeValue.slice(m[0].length); el.dataset.ic = '-' + m[2];
    const tmp = document.createElement('span'); tmp.innerHTML = phSVG(name, rest ? 'lead' : 'solo');
    el.insertBefore(tmp.firstChild, t);
    t.nodeValue = rest;
  }
}
var phQueued = false;
new MutationObserver(() => { if (phQueued) return; phQueued = true; requestAnimationFrame(() => { phQueued = false; phDecorate(document.body); }); })
  .observe(document.body, { childList: true, subtree: true });
phDecorate(document.getElementById('tabs'));
// 💎 → 8-bitowy kryształ w każdym tekście (sklep, ekwipunek, skrzynki, nagłówek); atrybuty i pola formularzy zostają bez zmian
var GEM8_IMG = '<img class="gem8" src="assets/gear8/crystal-sm.webp" alt="💎" draggable="false">';
function gem8Decorate(root = document.body) {
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: n => n.nodeValue.includes('💎') && !n.parentElement?.closest('textarea, input, select, option, script, style, [contenteditable], svg') ? 1 : 3 });
  const hits = []; while (w.nextNode()) hits.push(w.currentNode);
  for (const t of hits) {
    const span = document.createElement('span'); span.innerHTML = t.nodeValue.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]).replace(/((?:[·•–-]\s)?\S*\s?)💎/g, (m, w) => `<span class="gemw">${w}${GEM8_IMG}</span>`);   // klejnot nie spada sam do nowej linii
    t.replaceWith(...span.childNodes);
  }
}
var gemQueued = false;
new MutationObserver(() => { if (gemQueued) return; gemQueued = true; requestAnimationFrame(() => { gemQueued = false; gem8Decorate(); }); })
  .observe(document.body, { childList: true, subtree: true, characterData: true });
gem8Decorate();
;

/* ===== draw.js ===== */
'use strict';
/* ✏️ Szkicownik: rysowanie palcem / rysikiem / myszką (skojarzenie jako obrazek).
   openDrawPad(dataUrl?) → Promise<dataUrl | null>. Białe tło, kolory, grubość, gumka, cofnij, wyczyść. */

var PAD_COLORS = ['#111827', '#ef4444', '#f59e0b', '#22c55e', '#3b82f6', '#a855f7', '#ec4899', '#ffffff'];
var PAD_SIZES = [3, 6, 12, 22];

function openDrawPad(start) {
  return new Promise(resolve => {
    document.querySelector('.draw-ov')?.remove();
    const ov = document.createElement('div'); ov.className = 'draw-ov';
    ov.innerHTML = `<div class="draw-box">
      <div class="row nowrap draw-top"><b class="grow">✏️ Narysuj skojarzenie</b>
        <button class="sm" data-d="undo" title="Cofnij">↶</button><button class="sm" data-d="clear" title="Wyczyść">🗑️</button></div>
      <div class="draw-wrap"><canvas></canvas></div>
      <div class="draw-tools">
        <div class="draw-colors">${PAD_COLORS.map((c, i) => `<button data-c="${c}" class="${i ? '' : 'on'}" style="--c:${c}" title="${c === '#ffffff' ? 'gumka (biały)' : c}"></button>`).join('')}</div>
        <div class="draw-sizes">${PAD_SIZES.map((s, i) => `<button data-s="${s}" class="${i === 1 ? 'on' : ''}"><i style="width:${Math.min(22, s + 2)}px;height:${Math.min(22, s + 2)}px"></i></button>`).join('')}</div>
      </div>
      <div class="row nowrap"><button class="grow" data-d="cancel">Anuluj</button><button class="primary grow" data-d="ok">✓ Zapisz rysunek</button></div></div>`;
    document.body.append(ov);
    const cv = ov.querySelector('canvas'), ctx = cv.getContext('2d'), wrap = ov.querySelector('.draw-wrap');
    // płótno 4:3, w pikselach urządzenia (ostre linie na Retinie)
    const W = Math.min(wrap.clientWidth, 720), H = Math.round(W * .75), dpr = Math.min(2, devicePixelRatio || 1);
    cv.width = W * dpr; cv.height = H * dpr; cv.style.width = W + 'px'; cv.style.height = H + 'px';
    ctx.scale(dpr, dpr); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    const blank = () => { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H); };
    blank();
    const hist = [];
    const snap = () => { hist.push(ctx.getImageData(0, 0, cv.width, cv.height)); if (hist.length > 30) hist.shift(); };
    if (start) { const im = new Image(); im.onload = () => { ctx.drawImage(im, 0, 0, W, H); }; im.src = start; }
    let color = PAD_COLORS[0], size = PAD_SIZES[1], drawing = false, last = null, dirty = false;
    const pos = e => { const r = cv.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
    cv.addEventListener('pointerdown', e => {
      e.preventDefault(); cv.setPointerCapture(e.pointerId); snap(); drawing = true; dirty = true; last = pos(e);
      ctx.beginPath(); ctx.fillStyle = color; ctx.arc(last.x, last.y, size / 2, 0, Math.PI * 2); ctx.fill();
    });
    cv.addEventListener('pointermove', e => {
      if (!drawing) return; e.preventDefault();
      const pts = e.getCoalescedEvents ? e.getCoalescedEvents() : [e];
      ctx.strokeStyle = color; ctx.lineWidth = size * (e.pointerType === 'pen' && e.pressure ? .5 + e.pressure : 1);
      for (const pe of pts) { const p = pos(pe); ctx.beginPath(); ctx.moveTo(last.x, last.y); ctx.lineTo(p.x, p.y); ctx.stroke(); last = p; }
    });
    const end = () => { drawing = false; };
    cv.addEventListener('pointerup', end); cv.addEventListener('pointercancel', end);
    const close = v => { ov.remove(); resolve(v); };
    ov.addEventListener('click', e => {
      const b = e.target.closest('button'); if (!b) { if (e.target === ov) close(null); return; }
      if (b.dataset.c) { color = b.dataset.c; ov.querySelectorAll('[data-c]').forEach(x => x.classList.toggle('on', x === b)); }
      if (b.dataset.s) { size = +b.dataset.s; ov.querySelectorAll('[data-s]').forEach(x => x.classList.toggle('on', x === b)); }
      const d = b.dataset.d;
      if (d === 'undo' && hist.length) ctx.putImageData(hist.pop(), 0, 0);
      if (d === 'clear') { snap(); blank(); }
      if (d === 'cancel') close(null);
      if (d === 'ok') close(dirty || start ? cv.toDataURL('image/jpeg', .9) : null);
    });
  });
}
;

/* ===== weak.js ===== */
'use strict';
/* 📉 Mapa słabych punktów: które działy i które fiszki najczęściej uciekają.
   Liczymy z historii odpowiedzi (S.log, ostatnie 60 dni) + liczba zapomnień karty (lapses).
   Dział = pole „Dodatkowe” fiszki (np. „1. Środowisko wodne”), a gdy go brak – talia. */

var WEAK_DAYS = 60;
function weakData(deckId) {
  const since = Date.now() - WEAK_DAYS * DAY, byCard = {};
  for (const l of S.log) {
    if (l.t < since || (deckId && l.d !== deckId)) continue;
    const r = byCard[l.c] || (byCard[l.c] = { n: 0, bad: 0, hard: 0, last: 0 });
    r.n++; if (l.g === 1) r.bad++; if (l.g === 2) r.hard++; r.last = Math.max(r.last, l.t);
  }
  const cards = [], secs = {};
  for (const c of S.cards) {
    if (deckId && c.deckId !== deckId) continue;
    const r = byCard[c.id], note = noteById(c.noteId); if (!note) continue;
    const lapses = c.srs?.lapses || 0;
    if (!r && !lapses) continue;
    const n = r?.n || 0, bad = r?.bad || 0, hard = r?.hard || 0;
    // słabość: odsetek błędów (z wygładzeniem) + zapomnienia; niedawne pomyłki ważą więcej
    const score = (bad * 2 + hard + lapses * 1.5) / (n + 2) + (r && Date.now() - r.last < 3 * DAY && bad ? .3 : 0);
    const sec = (note.extra || '').replace(/<[^>]+>/g, '').trim().slice(0, 50) || (deckById(c.deckId)?.name || 'Talia');
    const key = c.deckId + '|' + sec;
    const sd = secs[key] || (secs[key] = { name: sec, deck: deckById(c.deckId)?.name || '', n: 0, ok: 0, cards: 0, weak: 0, ids: [] });
    sd.n += n; sd.ok += n - bad - hard * .5; sd.cards++; sd.ids.push(c.id); if (score >= .5) sd.weak++;
    cards.push({ c, score, n, bad, lapses, label: stripHtml(cardView(c).label || '') });
  }
  const sections = Object.values(secs).filter(s => s.n).map(s => ({ ...s, acc: Math.max(0, Math.round(s.ok / s.n * 100)) })).sort((a, b) => a.acc - b.acc);
  cards.sort((a, b) => b.score - a.score);
  return { sections, cards: cards.filter(x => x.score > .25) };
}
ROUTES.weak = (parts, q) => {
  const deckId = q?.get('deck') || '', d = deckId && deckById(deckId), W = weakData(deckId);
  const top = W.cards.slice(0, 20);
  const bar = acc => `<div class="weak-bar"><i style="width:${acc}%;background:${acc >= 85 ? 'var(--rev)' : acc >= 65 ? 'var(--hard)' : 'var(--lrn)'}"></i></div>`;
  return { tab: 'home', html: `<div class="row nowrap"><button class="iconbtn" data-go="${d ? '#/deck/' + d.id : '#/'}">‹</button><h1 class="grow">📉 Słabe punkty</h1></div>
    <p class="small muted" style="margin-top:-6px">${d ? esc(d.name) + ' · ' : 'Wszystkie talie · '}ostatnie ${WEAK_DAYS} dni. Dział = pole „Dodatkowe” fiszki.</p>
    ${top.length ? `<button class="primary block" data-go="#/study/${deckId || 'all'}/flip?cram=list&ids=${top.map(x => x.c.id).join(',')}">🔁 Powtórz moje najsłabsze ${top.length}</button>` : ''}
    <div class="card"><h2 style="margin-top:0">Działy – od najsłabszego</h2>
      ${W.sections.length ? W.sections.map(s => `<div class="weak-sec"><div class="row nowrap"><b class="grow nm">${esc(s.name)}</b><span class="small">${s.acc}%</span></div>${bar(s.acc)}
        <div class="row nowrap small muted"><span class="grow">${d ? '' : esc(s.deck) + ' · '}${s.cards} kart · ${s.weak} słabych</span>${s.weak ? `<button class="sm ghost" data-go="#/study/all/flip?cram=list&ids=${s.ids.join(',')}">Powtórz dział</button>` : ''}</div></div>`).join('')
        : '<p class="muted small">Jeszcze za mało powtórek – ucz się kilka dni, a tu pojawi się mapa.</p>'}</div>
    ${top.length ? `<div class="card"><h2 style="margin-top:0">Najczęściej zapominane</h2>${top.map((x, i) => `<div class="weak-card"><span class="wk-n">${i + 1}</span><div class="grow" style="min-width:0"><div class="nm">${esc(x.label)}</div>
      <small class="muted">${x.bad ? `❌ ${x.bad}× nie pamiętam` : ''}${x.bad && x.lapses ? ' · ' : ''}${x.lapses ? `🔁 ${x.lapses}× zapomniana` : ''} · ${x.n} powt.</small></div></div>`).join('')}</div>` : ''}` };
};
;

