var SPRITE_BOX = {"cat":[[18.8,42.5,81.2,100.0,54.2,50.8],[21.2,33.8,78.3,100.0,50.4,53.3],[16.2,20.4,83.3,100.0,55.2,56.2],[0.8,4.6,99.2,100.0,54.0,61.3]],"frog":[[29.9,64.4,70.1,100.0,54.9,30.6],[21.9,52.2,78.1,100.0,56.1,40.3],[18.7,38.8,81.3,100.0,51.1,40.3],[0.7,15.8,99.3,100.0,55.9,86.0]],"dog":[[18.3,36.2,81.7,100.0,59.9,38.1],[19.3,22.0,80.3,100.0,59.2,42.2],[12.8,15.6,87.2,100.0,52.1,66.5],[1.8,1.8,98.2,100.0,51.8,88.1]],"owl":[[32.0,61.7,68.0,99.2,54.0,21.6],[24.2,55.5,75.8,99.2,53.2,25.0],[19.5,50.0,80.5,99.2,53.8,36.6],[0.8,46.9,99.2,98.4,53.5,59.1]],"hamster":[[32.0,64.8,67.2,98.4,53.1,19.5],[25.8,54.7,74.2,98.4,50.8,29.1],[21.9,50.0,78.1,98.4,51.5,32.8],[1.6,43.0,98.4,98.4,53.2,43.8]],"fox":[[22.9,43.2,77.1,100.0,56.2,33.9],[18.5,30.4,81.5,100.0,58.4,37.4],[11.5,21.1,88.1,100.0,53.1,63.0],[6.6,1.8,93.4,100.0,53.7,73.1]],"beast":[[26.6,64.8,72.7,98.4,51.0,27.7],[24.2,55.5,75.8,98.4,55.1,25.0],[19.5,54.7,80.5,98.4,52.2,36.6],[1.6,47.7,98.4,98.4,56.5,58.1]],"rabbit":[[23.7,42.7,76.3,100.0,52.8,29.9],[20.9,26.1,78.7,100.0,50.7,40.8],[15.2,15.6,84.4,100.0,47.6,53.6],[7.6,1.9,91.9,100.0,49.8,73.0]],"phoenix":[[25.6,45.8,74.4,100.0,57.1,27.7],[19.7,30.3,79.8,100.0,51.9,50.8],[12.6,19.7,87.4,100.0,51.9,69.3],[3.4,1.7,96.2,100.0,49.8,92.9]],"dragon":[[23.2,49.2,76.4,100.0,54.1,36.6],[22.0,39.0,78.0,100.0,48.6,53.3],[10.6,15.9,89.4,100.0,52.0,74.8],[8.1,1.6,91.9,100.0,52.2,76.8]]};
var spriteVars = (line, f) => { const b = SPRITE8[line] && isPixelLine(line) && SPRITE_BOX[line]?.[f]; if (!b) return ''; const [x0, y0, x1, y1, hx, hw] = b; return ` s8" style="--x0:${x0};--y0:${y0};--x1:${x1};--y1:${y1};--hx:${hx};--hw:${hw};--bh:${y1 - y0}`; };
var heroStyle = () => 'pixel';   // tylko pixel art – rysowane postacie usunięte
var isPixelLine = line => heroStyle() === 'pixel' && PIXEL_LINES.includes(line);
function heroArt(line, f = 0, g = 'w') {
  if (!isPixelLine(line)) return charSVG(line, f, g);
  if (SPRITE8[line]) return `<img class="charpx s8" src="assets/pixel/${line}8-${f}.webp" alt="" draggable="false">`;
  return `<img class="charpx" src="assets/pixel/${line}-${f}-${g}-${PX_SIZES[f]}.png" alt="" draggable="false">`;
}
// obrazek postaci nie wczytał się (słaby zasięg) – jeszcze jedna próba po chwili zamiast „?”
document.addEventListener('error', e => {
  const im = e.target; if (im?.tagName !== 'IMG' || !im.classList.contains('charpx') || im.dataset.retry) return;
  im.dataset.retry = '1'; const src = im.getAttribute('src').split('?')[0];
  setTimeout(() => { if (im.isConnected) im.src = src + '?r=' + Date.now(); }, 900);
}, true);
;

