function finishBattle() {
  const sc = scores();
  let won = sc.my > sc.opp ? 1 : sc.my < sc.opp ? -1 : 0;
  if (B.oppLeft && !B.oppDone) won = 1;
  if (won === 0 && B.myTotalMs && B.oppTotalMs) won = B.myTotalMs < B.oppTotalMs ? 1 : B.myTotalMs > B.oppTotalMs ? -1 : 0;
  B.phase = 'end'; B.result = { ...sc, won };
  const rec = { id: B.id, t: Date.now(), mode: B.setup.mode, disc: B.setup.disc, deck: B.setup.deckName, opp: B.opp?.nick, oppAvatar: B.opp?.avatar,
    my: sc.my, them: sc.opp, n: sc.n, won, abcd: !!B.setup.opts?.abcd, bot: B.role === 'bot', myMs: B.myTotalMs, oppMs: B.oppTotalMs, blur: B.myBlur };
  if (B.role !== 'bot' && Number.isFinite(B.opp?.elo)) { rec.oppElo = B.opp.elo; rec.elo = eloDelta(myElo(), clamp(B.opp.elo, 100, 3000), won, S.battles.filter(b => b.elo != null).length); }
  S.battles.push(rec);
  if (won === 1) {
    addItem('case', 'basic', 1, 'case-' + B.id);
    S.stats.battleWins = (S.stats.battleWins || 0) + 1;
    const streakNow = (() => { let n = 0; for (let i = S.battles.length - 1; i >= 0 && S.battles[i].won === 1; i--) n++; return n; })();
    S.stats.winStreak = Math.max(S.stats.winStreak || 0, streakNow);
    emit('battleWin', rec);
    setTimeout(() => celebrate('🏆 Zwycięstwo!', `+${battleReward(rec)} 💎 i darmowa skrzynka`), 300);
  } else if (won === 0) toast('🤝 Remis!');
  else {
    toast('💪 Tym razem przegrana – rewanż?', 3000);
    // GIF wygranej przeciwnika (z jego ekwipunku) – zwycięzcę widać u wszystkich
    if (B.role !== 'bot' && typeof showWinnerGif === 'function') setTimeout(() => showWinnerGif(B.opp?.winGif, B.opp?.nick), 500);
  }
  save(); B.ch?.send({ t: 'done', total: B.myTotalMs }); renderBattle();
}
function maybeRematch() {
  if (!(B.rmMine && B.rmTheirs) || B.role !== 'host') return renderBattle();
  const st = B.setup, o = st.opts || {};
  let fresh;
  if (st.mode === 'mem') fresh = { ...st, seed: Math.random() * 1e9 | 0 };
  else { const c = st.deckId && deckById(st.deckId) ? battleCards(st.deckId, st.cards.length, o.dir || 'qa', o.abcd) : []; fresh = { ...st, cards: c.length >= 3 ? c : shuffle([...st.cards]) }; }
  B.ch.send({ t: 'rs', setup: fresh });
  restartBattle(fresh);
}
// nowa runda na tym samym kanale, z tym samym przeciwnikiem
function restartBattle(setup) {
  const keep = { ch: B.ch, role: B.role, code: B.code, opp: B.opp, lobby: null };
  clearInterval(B.uiTimer); GAME = null;
  B = { id: uid(), phase: 'wait', myAns: [], oppAns: [], myBlur: 0, oppBlur: 0, lastOpp: Date.now(), sabUsed: 0, sabLast: 0, li: 0, lflip: false, seen: new Set([0]), ...keep, setup };
  toast('🔁 Rewanż! Powodzenia', 2000);
  startCountdown(); go('#/battle');
}
function quitBattle() {
  if (B) { if (B.phase !== 'end') B.ch?.send({ t: 'bye' }); B.ch?.close(); (B.botTimers || []).forEach(clearTimeout); clearInterval(B.uiTimer); }
  B = null; GAME = null; go('#/battles');
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState !== 'hidden' || !B || B.phase !== 'recall') return;
  B.myBlur++; B.ch?.send({ t: 'blur' });
  if (B.setup.mode === 'cards') { B.frozenUntil = 0; submitAnswer(''); toast('⚠️ Wyjście z aplikacji w trakcie odpowiedzi = pytanie stracone', 4000); }
});

// ============================================================ Sabotaże
function useSabotage(k) {
  const sb = SABOTAGE[k]; if (!B || !sb || !B.setup.opts?.sab) return;
  if (B.phase !== 'recall' && !(B.setup.mode === 'mem' && B.phase === 'learn')) return toast('Sabotaży używasz w trakcie walki');
  if (sb.cardsOnly && B.setup.mode !== 'cards') return;
  if (B.sabUsed >= SAB_MAX) return toast(`Limit ${SAB_MAX} sabotaży na bitwę`);
  if (Date.now() - B.sabLast < SAB_COOLDOWN) return toast('Chwilę… sabotaż się ładuje ⏳');
  if (!sb.self && B.oppDone) return toast('Przeciwnik już skończył');
  if (!spend(sb.cost, 'sab-' + k)) return;
  B.sabUsed++; B.sabLast = Date.now(); S.stats.sabUsed = (S.stats.sabUsed || 0) + 1; save();
  setTimeout(renderBattle, SAB_COOLDOWN + 100);
  if (sb.self) { B.shieldOn = true; toast('🛡️ Tarcza aktywna'); return renderBattle(); }
  floatText(`${sb.icon} ${sb.name}!`, true);
  if (B.role === 'bot') return botReceiveSabotage(k);
  B.ch?.send({ t: 'sab', k });
}
function receiveSabotage(k) {
  const sb = SABOTAGE[k]; if (!sb || B.phase === 'end') return;
  if (B.shieldOn) { B.shieldOn = false; B.ch?.send({ t: 'sabblock' }); toast(`🛡️ Tarcza zablokowała: ${sb.icon} ${sb.name}`); return; }
  if (k === 'freeze') { B.frozenUntil = Date.now() + 5000; setTimeout(renderBattle, 5100); }
  if (k === 'fog') { B.fogUntil = Date.now() + 7000; setTimeout(renderBattle, 7100); }
  if (k === 'undo') {
    const idx = [...B.myAns].reverse().findIndex(a => a.ok);
    if (idx < 0 || B.myDone) { B.ch?.send({ t: 'sabnone' }); return; }
    const a = B.myAns.splice(B.myAns.length - 1 - idx, 1)[0];
    B.order.push(a.i); B.ch?.send({ t: 'unans', i: a.i });
  }
  toast(`${sb.icon} ${B.opp?.nick || 'Przeciwnik'} użył: ${sb.name}!`, 3000);
  tick(160, .25, .15);
}

// ============================================================ Bot
// 🧑 „ludzki” bot: czas = reakcja + czytanie pytania + pisanie odpowiedzi (losowo, czasem chwila zawahania),
// po błędzie zwalnia i myli się częściej (tilt), na fali przyspiesza; pomyłki: literówka, pomylenie z inną kartą albo pusto
var randn = () => { let u = 0, v = 0; while (!u) u = Math.random(); while (!v) v = Math.random(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
function humanMs(q, a, acc, mood = 0) {
  const read = 900 + String(q || '').length * 38, type = String(a || '').length * (230 - 90 * acc), react = 600 + Math.random() * 900;
  const hes = Math.random() < .18 ? 1500 + Math.random() * 3500 : 0;   // „hmm…”
  return Math.max(1400, (react + read + type + hes) * Math.exp(.25 * randn()) * (1 + .12 * mood));
}
function humanWrong(card, cards) {
  const r = Math.random(), other = cards.filter(c => c.a !== card.a);
  if (r < .45) return typo(card.a); if (r < .8 && other.length) return other[Math.random() * other.length | 0].a; return '';
}
function botAfter(ms, fn) { const t = setTimeout(() => { if (B && B.role === 'bot' && B.phase !== 'end') fn(); }, ms); (B.botTimers = B.botTimers || []).push(t); }
function botPlay() {
  const { acc, a, b } = B.botP;
  const st = B.setup;
  if (st.mode === 'mem') {
    const items = GAME.items, n = items.length;
    const want = (15 + n * 2.2 * (1.3 - acc)) * 1000, learn = GAME.t ? Math.min(GAME.t * 1000, want) : want;
    // pamięć: im dłuższy ciąg i krótszy czas, tym więcej pomyłek; błędy często „seriami” (zgubiony obraz = kilka elementów)
    const p = clamp(acc * (1 - Math.min(.5, n / 250)) * clamp(learn / (n * 2500), .5, 1.05), .05, .97);
    const ans = []; let lost = 0;
    items.forEach(x => { if (lost > 0) { lost--; ans.push(null); } else if (Math.random() < p) ans.push(x); else { ans.push(null); lost = Math.random() < .5 ? 1 + (Math.random() * 2 | 0) : 0; } });
    const rec = n * (700 + Math.random() * 600);
    botAfter(learn, () => { B.oppReady = true; B.oppLearnMs = learn; renderBattle(); });
    botAfter(learn + rec, () => { B.oppMem = ans; B.oppDone = true; B.oppTotalMs = learn + rec; maybeFinish(); renderBattle(); });
    return;
  }
  const n = st.cards.length, cap = (st.opts?.learnSec || 0) * 1000;
  const want = n * (5 + 7 * (1 - acc)) * 1000 * (0.8 + Math.random() * .4), learn = cap ? Math.min(cap, want) : want;
  B.bot = { queue: shuffle(st.cards.map((_, i) => i)), t: 0, acc, a, b, learn };
  botAfter(learn, () => { B.oppReady = true; B.oppLearnMs = learn; renderBattle(); botNext(); });
  if (st.opts?.sab && acc > .5) [learn + 9000, learn + 20000].slice(0, acc > .75 ? 2 : 1).forEach(t => botAfter(t + Math.random() * 6000, () => {
    if (B.phase === 'recall') { receiveSabotage(Math.random() < .5 ? 'freeze' : 'fog'); renderBattle(); } }));
}
function botNext() {
  const bt = B.bot; if (!bt.queue.length) { B.oppDone = true; B.oppTotalMs = Date.now() - B.learnStart; maybeFinish(); return renderBattle(); }
  const ansLimit = (B.setup.opts?.ansSec || 999) * 1000;
  const i0 = bt.queue[0], c0 = B.setup.cards[i0], mood = bt.mood || 0;
  // trudniejsza karta (długa odpowiedź) = dłuższe myślenie; pod presją limitu czasu bot się spieszy
  const d = Math.min(ansLimit * (.6 + Math.random() * .35), humanMs(c0?.q, c0?.a, bt.acc, mood) + (bt.frozen || 0)); bt.frozen = 0;
  botAfter(d, () => {
    const i = bt.queue.shift(), card = B.setup.cards[i];
    const ok = Math.random() < clamp(botCardChance(bt.acc, B.setup.cards.length, bt.learn, card.a.length) - .06 * Math.max(0, mood) + .03 * Math.max(0, -mood), .05, .97);
    bt.mood = ok ? Math.max(-3, mood - 1) : Math.min(3, mood + 1);
    B.oppAns = B.oppAns.filter(x => x.i !== i);
    B.oppAns.push({ i, given: ok ? card.a : humanWrong(card, B.setup.cards), ok, ms: d }); if (ok && B.setup.opts?.live !== false) hitFx('me'); maybeFinish(); if (B.phase === 'end') return;
    renderBattle(); botNext();
  });
}
function botReceiveSabotage(k) {
  const bt = B.bot;
  if (k === 'freeze' && bt) bt.frozen = 5000;
  if (k === 'undo' && bt) {
    const idx = [...B.oppAns].reverse().findIndex(a => a.ok);
    if (idx >= 0 && !B.oppDone) { const a = B.oppAns.splice(B.oppAns.length - 1 - idx, 1)[0]; bt.queue.push(a.i); toast('⏪ Cofnięcie zadziałało!'); }
    else toast('⏪ Nie było czego cofnąć');
  }
  renderBattle();
}

// ============================================================ Efekty bitwy
function hitFx(who) {
  const el = $(who === 'me' ? '#hp-me' : '#hp-opp'); if (!el) return;
  el.classList.remove('hit'); void el.offsetWidth; el.classList.add('hit');
  tick(who === 'me' ? 220 : 520, .08, .1);
}
function stickerFx(k, from, shiny) {
  const s = stickerById(k); if (!s) return;
  const el = document.createElement('div'); el.className = `stfly ${s.r}${fxCls(+shiny || 0)}${S.settings.stickerAnim !== false ? ' anim st-' + s.id : ''}`; el.style.setProperty('--rc', RARITY[s.r].color);
  el.innerHTML = `<span>${stE(s)}</span><small>${esc(from || 'Ty')}: ${esc(s.name)}${shiny ? ' ✨' : ''}</small>`;
  document.body.append(el); setTimeout(() => el.remove(), 2600);
  if (s.r === 'legendary' || s.r === 'mythic' || shiny) confetti(60);
}
var lastSticker = 0;

// ============================================================ Widoki
function hpBars() {
  const sc = B.setup ? scores() : { my: 0, opp: 0, n: 1 };
  const reveal = (B.setup?.mode !== 'mem' && B.setup?.opts?.live !== false) || B.phase === 'end';
  const myHp = 100 - (reveal ? sc.opp : 0) / sc.n * 100, oppHp = 100 - (reveal ? sc.my : 0) / sc.n * 100;
  const tug = clamp(50 + ((reveal ? sc.my - sc.opp : 0) / sc.n) * 50, 3, 97);
  const op = B.opp || { nick: '…', avatar: '❔' }, m = me();
  const state = (ready, done) => done ? '✅ skończył' : ready ? '⚔️ odpowiada' : ['learn', 'recall', 'waitopp'].includes(B.phase) ? '📖 uczy się' : '';
  const sc2 = ids => typeof showcaseHTML === 'function' ? `<span class="showcase">${showcaseHTML(ids)}</span>` : '';
  return `<div class="arena">
    <div class="fighter"><div class="row nowrap"><span class="av">${avatarHTML(m, 34)}</span>${sc2(m.showcase)}</div><b class="nm">${esc(m.nick)}${B.shieldOn ? ' 🛡️' : ''}</b><div class="hp" id="hp-me"><div style="width:${myHp}%"></div></div><small>${reveal ? Math.round(myHp) + ' HP · ' : ''}${state(B.phase !== 'learn', B.myDone)}</small></div>
    <div class="vs">VS</div>
    <div class="fighter r"><div class="row nowrap">${sc2(op.showcase)}<span class="av">${avatarHTML(op, 34)}</span></div><b class="nm">${esc(op.nick)}</b><div class="hp opp" id="hp-opp"><div style="width:${oppHp}%"></div></div><small>${reveal ? Math.round(oppHp) + ' HP · ' : ''}${state(B.oppReady, B.oppDone)}</small></div>
  </div><div class="tug"><div class="tugfill" style="width:${tug}%"></div><span class="knot" style="left:${tug}%">⚔️</span></div>
  ${reveal ? '' : '<p class="small muted center" style="margin-top:-8px">Wynik przeciwnika zobaczysz na końcu 🤫</p>'}`;
}
function stickerBar() {
  return `<div class="stbar">${ownedStickers().map(id => { const s = stickerById(id); return `<button class="${fxCls(shinyLv(id)).trim()}" data-act="bt-sticker" data-k="${id}" style="--rc:${RARITY[s.r].color}">${stE(s)}</button>`; }).join('')}</div>`;
}
function sabotageBar() {
  if (!B.setup.opts?.sab) return '';
  const left = SAB_MAX - B.sabUsed, cool = Date.now() - B.sabLast < SAB_COOLDOWN;
  return `<div class="sabbar"><span class="small muted">Sabotaże (${left}) · 💎 ${coins()}</span><div class="row nowrap">${Object.entries(SABOTAGE).filter(([, s]) => !s.cardsOnly || B.setup.mode === 'cards').map(([k, s]) =>
    `<button class="sab" data-act="bt-sab" data-k="${k}" ${left <= 0 || cool || coins() < s.cost ? 'disabled' : ''} title="${esc(s.desc)}"><span>${s.icon}</span><small>${s.cost}💎</small></button>`).join('')}</div></div>`;
}
function overlays() {
  let o = '';
  if (B.frozenUntil > Date.now()) o += `<div class="freeze"><div>❄️<b>Zamrożony!</b><small>${Math.ceil((B.frozenUntil - Date.now()) / 1000)} s</small></div></div>`;
  return o;
}
function renderBattle() { if (parseRoute().parts[0] === 'battle') render(); }
var speech = null;
ROUTES.battle = () => {
  if (!B) return { html: `<p>Brak aktywnej bitwy. <a href="#/battles">Bitwy</a></p>` };
  const close = `<button class="iconbtn" data-act="bt-quit">✕</button>`;
  const o = B.setup?.opts || {};
  if (B.phase === 'wait') {
    const link = APP_URL() + '#/battles?join=' + B.code;
    return { focus: true, html: `<div class="studybar">${close}<div class="title">⚔️ Pokój bitwy</div></div>
      <div class="card center"><p>Podaj znajomemu kod:</p><div class="code">${B.code}</div>
      <p class="small muted">${B.setup.mode === 'cards' ? `${B.setup.opts?.abcd ? '🅰️ Quiz ABCD' : 'Fiszki'}: ${esc(B.setup.deckName)} · ${B.setup.cards.length} kart` : `Pamięć: ${DISC[B.setup.disc].name} · ${memNT(B.setup)[0]}`}</p>
      ${rulesHTML(B.setup)}
      <button class="primary block" data-act="bt-share" data-link="${esc(link)}">📤 Wyślij zaproszenie</button>
      <div class="spinner"></div><p class="small muted">Czekam na przeciwnika…</p></div>` };
  }
  if (B.phase === 'joining' || B.phase === 'seeking') {
    return { focus: true, html: `<div class="studybar">${close}<div class="title">⚔️ ${B.phase === 'seeking' ? 'Szukam przeciwnika' : 'Dołączam'}</div></div>
      <div class="card center"><div class="spinner"></div><p>${B.phase === 'seeking' ? 'Szukam gracza, który też chce walczyć…' : `Łączę z pokojem <b>${esc(B.code)}</b>…`}</p>
      ${B.phase === 'seeking' && Date.now() - B.seekStart > 25000 ? `<p class="small muted">Nikogo jeszcze nie ma.</p><button class="block" data-act="bt-bot-now">🤖 Zagraj z botem</button>` : ''}</div>` };
  }
  if (B.phase === 'countdown') {
    const el = Math.max(0, 3.5 - (B.goAt - Date.now()) / 1000).toFixed(2);
    return { focus: true, html: hpBars() + `<div class="getready"><b>Przygotuj się…</b><div class="readybar"><div style="animation-delay:-${el}s"></div></div></div><p class="center">${B.setup.mode === 'cards' ? `📖 Przejrzyj ${B.setup.cards.length} fiszek, potem ${B.setup.opts?.abcd ? 'quiz ABCD – liczą się poprawne odpowiedzi' : 'test z pamięci'}` : `🧠 ${DISC[B.setup.disc].name}: zapamiętaj i odtwórz`}</p>${rulesHTML(B.setup)}` };
  }
  const head = `<div class="studybar">${close}<div class="title">⚔️ Bitwa</div><b class="timer" id="btimer"></b></div>` + hpBars();
  if (B.setup.mode === 'mem' && (B.phase === 'learn' || B.phase === 'recall') && GAME?.battle) {
    onMount(mountGameTimer);
    const inner = GAME.phase === 'memo' ? gameMemo(GAME, DISC[GAME.d]) : gameRecall(GAME, DISC[GAME.d]);
    return { focus: true, html: `<div class="studybar">${close}<div class="title">⚔️ ${GAME.phase === 'memo' ? 'Zapamiętuj' : 'Odtwórz'}</div><b id="gtimer" class="timer"></b></div>${hpBars()}
      <div class="${B.fogUntil > Date.now() ? 'fog' : ''}">${inner}</div>${sabotageBar()}${stickerBar()}${overlays()}` };
  }
  if (B.phase === 'learn') {
    onMount(battleTimer);
    const cards = B.setup.cards, c = cards[B.li], seen = B.seen.size;
    return { focus: true, html: head + `<div class="row small muted"><span class="grow">Fiszka ${B.li + 1}/${cards.length} · obejrzane ${seen}/${cards.length}</span>${o.learnSec ? '' : '<span>bez limitu czasu</span>'}</div>
      ${progress(seen / cards.length, true)}
      <div class="card flash learncard" data-act="bt-flip">${B.lflip ? `<div class="ctext">${fmt(c.q)}</div><hr><div class="ctext"><b>${fmt(c.a)}</b></div>` : `<div class="ctext">${fmt(c.q)}</div><p class="small muted">stuknij, aby odwrócić</p>`}</div>
      <div class="row nowrap"><button class="grow" data-act="bt-lnav" data-d="-1" ${B.li ? '' : 'disabled'} style="min-height:52px">‹ Poprzednia</button>
        <button class="grow ${B.lflip ? 'primary' : ''}" data-act="${B.lflip ? 'bt-lnav' : 'bt-flip'}" data-d="1" style="min-height:52px">${B.lflip ? (B.li < cards.length - 1 ? 'Następna ›' : 'Od początku ↺') : 'Odwróć'}</button></div>
      <div class="answerbar"><button class="${seen === cards.length ? 'primary' : ''} block" data-act="bt-ready" style="min-height:56px">🧪 Przejdź do testu${seen < cards.length ? ` (obejrzane ${seen}/${cards.length})` : ''}</button></div>${stickerBar()}` };
  }
  if (B.phase === 'recall') {
    const i = B.order[B.cur], it = B.setup.cards[i];
    const frozen = B.frozenUntil > Date.now();
    onMount(() => {
      battleTimer();
      const inp = $('#bt-in'); if (!inp) return;
      // odświeżenie ekranu (np. trafienie przeciwnika) nie kasuje tego, co wpisujesz
      if (B.draft?.i === i) inp.value = B.draft.v;
      inp.addEventListener('input', () => { B.draft = { i, v: inp.value }; });
      if (!frozen) { inp.focus({ preventScroll: true }); inp.setSelectionRange(inp.value.length, inp.value.length); }
      inp.addEventListener('paste', e => { e.preventDefault(); toast('Wklejanie jest wyłączone w bitwie 😉'); });
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); submitAnswer(inp.value.trim()); } });
    });
    const hasSpeech = !!(window.SpeechRecognition || window.webkitSpeechRecognition);
    return { focus: true, html: head + `<div class="row small muted"><span class="grow">Pytanie ${B.cur + 1}/${B.order.length}</span><span id="cardleft"></span></div>
      <div class="card flash${it.opts ? ' short' : ''}${B.fogUntil > Date.now() ? ' fog' : ''}"><div class="ctext">${fmt(it.q)}</div></div>
      ${it.opts ? `<div class="abcd">${it.opts.map((x, k) => `<button data-act="bt-abcd" data-k="${k}" ${frozen ? 'disabled' : ''}><b>${'ABCD'[k]}</b><span>${fmt(x)}</span></button>`).join('')}</div>
      <div class="spacer"></div><button class="block" data-act="bt-skip">Nie wiem</button>`
      : `<div class="row nowrap"><input id="bt-in" class="grow" placeholder="Odpowiedź…" autocomplete="off" autocapitalize="off" spellcheck="false" ${frozen ? 'disabled' : ''}>
        ${hasSpeech ? `<button data-act="bt-mic" class="${speech ? 'primary' : ''}" title="Powiedz odpowiedź">🎤</button>` : ''}</div>
      <div class="spacer"></div><div class="row nowrap"><button class="grow" data-act="bt-skip">Nie wiem</button><button class="primary grow" data-act="bt-submit">Odpowiedz ➤</button></div>`}
      ${sabotageBar()}${stickerBar()}${overlays()}` };
  }
  if (B.phase === 'waitopp') {
    return { focus: true, html: head + `<div class="card center"><div class="spinner"></div><p>Skończyłeś! Czekam, aż ${esc(B.opp?.nick || 'przeciwnik')} skończy…</p>
      ${Date.now() - B.lastOpp > 90000 && B.role !== 'bot' ? '<button class="block" data-act="bt-walkover">Przeciwnik nie odpowiada – zakończ (walkower)</button>' : ''}</div>${sabotageBar()}${stickerBar()}` };
  }
  // koniec
  if (B.review) {
    const R = B.review, c = R.list[R.i];
    if (!c) return { focus: true, html: `<div class="studybar"><button class="iconbtn" data-act="bt-rv-close">✕</button><div class="title">🔁 Moje błędy</div></div>
      <div class="card center"><div style="font-size:50px">✅</div><p>Przejrzane wszystkie błędy.</p><button class="primary block" data-act="bt-rv-close">Wróć do wyniku</button></div>` };
    return { focus: true, html: `<div class="studybar"><button class="iconbtn" data-act="bt-rv-close">✕</button><div class="title">🔁 Moje błędy</div><span class="small muted">${R.i + 1}/${R.list.length}</span></div>
      ${progress(R.i / R.list.length)}<div class="card flash"><div class="ctext">${fmt(c.q)}</div>${R.shown ? `<hr><div class="ctext"><b>${fmt(c.a)}</b></div>` : ''}</div>
      <div class="answerbar">${R.shown ? '<button class="primary block" data-act="bt-rv-next" style="min-height:56px">Dalej ›</button>' : '<button class="primary block" data-act="bt-rv-show" style="min-height:56px">Pokaż odpowiedź</button>'}</div>` };
  }
  const r = B.result, rec = S.battles.find(x => x.id === B.id);
  const caseKind = hasItem('case', 'epic') ? 'epic' : 'basic';
  return { focus: true, html: `<div class="studybar">${close}<div class="title">⚔️ Wynik</div></div>${hpBars()}
    <div class="card center result-${r.won}"><div style="font-size:60px">${r.won === 1 ? '🏆' : r.won === 0 ? '🤝' : '💪'}</div>
      <h2 style="margin:4px 0">${r.won === 1 ? 'Zwycięstwo!' : r.won === 0 ? 'Remis' : 'Porażka'}</h2>
      <p><b>${r.my}</b> : <b>${r.opp}</b> <span class="muted">(z ${r.n})</span></p>
      <p class="small muted">Twój czas: ${fmtTime(B.myTotalMs || 0)}${B.oppTotalMs ? ` · przeciwnik: ${fmtTime(B.oppTotalMs)}` : ''}${B.myBlur || B.oppBlur ? ` · wyjścia z aplikacji: Ty ${B.myBlur}, przeciwnik ${B.oppBlur}` : ''}</p>
      <p><b class="coins">+${rec ? battleReward(rec) : 0} 💎</b>${rec?.elo != null ? ` <b class="${rec.elo >= 0 ? 'c-rev' : 'c-lrn'}">${rec.elo >= 0 ? '+' : ''}${rec.elo} Elo</b> → ${eloHTML(myElo())}` : rec?.bot ? ' <span class="small muted">(bot – bez Elo)</span>' : ''}</p>
      ${r.won === 1 && hasItem('case', caseKind) ? `<button class="primary block" data-go="#/case/${caseKind}?free=1" style="min-height:56px">🎁 Otwórz darmową skrzynkę!</button><div class="spacer"></div>` : ''}
      ${B.role === 'bot' ? `<div class="row"><button class="primary grow" data-act="bt-rematch">🔁 Rewanż</button><button class="grow" data-act="bt-new-opp">🔎 Nowy przeciwnik</button></div>`
        : B.oppLeft ? `<p class="small muted">${esc(B.opp?.nick || 'Przeciwnik')} opuścił bitwę.</p><button class="primary block" data-act="bt-new-opp">🔎 Znajdź nowego przeciwnika</button>`
        : `<div class="row">${B.rmMine ? `<button class="grow" disabled>⏳ Czekam na zgodę ${esc(B.opp?.nick || '')}…</button>`
            : `<button class="primary grow${B.rmTheirs ? ' pulse' : ''}" data-act="bt-rm">${B.rmTheirs ? `✅ Przyjmij rewanż od ${esc(B.opp?.nick || '')}` : `🔁 Rewanż z ${esc(B.opp?.nick || 'tym graczem')}`}</button>`}
            <button class="grow" data-act="bt-new-opp">🔎 Nowy przeciwnik</button></div>`}
      <div class="spacer"></div><button class="ghost block" data-act="bt-quit">Zakończ</button></div>
    ${battleReviewHTML()}` };
};
// Analiza po bitwie: skuteczność obu graczy i pytanie po pytaniu – co kto odpowiedział
function battleReviewHTML() {
  const op = B.opp?.nick || 'Przeciwnik', m = me();
  const pct = (a, n) => n ? Math.round(a / n * 100) : 0;
  const avg = arr => arr.length ? arr.reduce((x, y) => x + (y.ms || 0), 0) / arr.length / 1000 : 0;
  const statRow = (label, mine, theirs) => `<div class="cmprow"><b>${mine}</b><span>${label}</span><b>${theirs}</b></div>`;
  if (B.setup.mode === 'mem') {
    const items = GAME?.items || memItems(B.setup.disc, memNT(B.setup)[0], B.setup.seed), D = DISC[B.setup.disc];
    const mine = B.myMem || [], theirs = B.oppMem || [], sc = scores();
    const cell = (v, x) => v === x ? `<span class="res ok">${D.tile(x)}</span>` : `<span class="res bad">${D.tile(x)}<small>${v != null ? D.tile(v) : '–'}</small></span>`;
    return `<div class="card"><h3 style="margin-top:0">📊 Analiza bitwy</h3>
      <div class="cmphead"><span>${avatarHTML(m, 24)} Ty</span><span></span><span>${esc(op)} ${avatarHTML(B.opp || {}, 24)}</span></div>
      ${statRow('skuteczność', pct(sc.my, sc.n) + '%', pct(sc.opp, sc.n) + '%')}
      ${statRow('poprawne', `${sc.my}/${sc.n}`, `${sc.opp}/${sc.n}`)}
      ${statRow('zapamiętywanie', fmtTime(B.myLearnMs || 0), B.oppLearnMs ? fmtTime(B.oppLearnMs) : '–')}
      <h4>Twoje odpowiedzi</h4><p class="small muted">Zielone – dobrze; czerwone – pod spodem to, co wpisałeś.</p><div class="results ${B.setup.disc}">${items.map((x, i) => cell(mine[i], x)).join('')}</div>
      <h4>Odpowiedzi: ${esc(op)}</h4><div class="results ${B.setup.disc}">${items.map((x, i) => cell(theirs[i], x)).join('')}</div></div>`;
  }
  const cards = B.setup.cards, n = cards.length;
  const myOk = B.myAns.filter(a => a.ok), opOk = B.oppAns.filter(a => a.ok);
  const both = cards.filter((_, i) => !B.myAns.find(a => a.i === i)?.ok && !B.oppAns.find(a => a.i === i)?.ok).length;
  const ans = (a, c) => !a ? '<span class="muted">—</span>' : a.ok
    ? `<span class="c-rev">✓ ${esc(a.given || c.a)}</span>` : `<span class="c-lrn">✗ ${esc(a.given || '(brak odpowiedzi)')}</span>`;
  const rows = cards.map((c, i) => { const a = B.myAns.find(x => x.i === i), b = B.oppAns.find(x => x.i === i);
    const cls = a?.ok ? (b?.ok ? '' : 'win') : (b?.ok ? 'lose' : 'both');
    return `<div class="qrev ${cls}"><div class="q">${i + 1}. ${esc(c.q)}</div><div class="a">✔ ${esc(c.a)}</div>
      <div class="two"><div><small>Ty${a?.ms ? ` · ${(a.ms / 1000).toFixed(1)} s` : ''}</small>${ans(a, c)}</div><div><small>${esc(op)}${b?.ms ? ` · ${(b.ms / 1000).toFixed(1)} s` : ''}</small>${ans(b, c)}</div></div></div>`; }).join('');
  const mistakes = cards.filter((_, i) => !B.myAns.find(a => a.i === i)?.ok);
  return `<div class="card"><h3 style="margin-top:0">📊 Analiza bitwy</h3>
    <div class="cmphead"><span>${avatarHTML(m, 24)} Ty</span><span></span><span>${esc(op)} ${avatarHTML(B.opp || {}, 24)}</span></div>
    ${statRow('skuteczność', pct(myOk.length, n) + '%', pct(opOk.length, n) + '%')}
    ${statRow('poprawne', `${myOk.length}/${n}`, `${opOk.length}/${n}`)}
    ${statRow('błędy', n - myOk.length, n - opOk.length)}
    ${statRow('śr. czas odp.', avg(B.myAns).toFixed(1) + ' s', B.oppAns.length ? avg(B.oppAns).toFixed(1) + ' s' : '–')}
    ${statRow('nauka', fmtTime(B.myLearnMs || 0), B.oppLearnMs ? fmtTime(B.oppLearnMs) : '–')}
    <div class="legend small muted"><span class="dot win"></span>tylko Ty dobrze <span class="dot lose"></span>tylko ${esc(op)} <span class="dot both"></span>oboje źle</div>
    ${rows}
    ${both ? `<p class="small muted">${both} ${plural(both, 'pytanie', 'pytania', 'pytań')} sprawiło trudność obojgu.</p>` : ''}
    ${mistakes.length ? `<button class="block" data-act="bt-cram-mistakes">🔁 Powtórz moje błędy (${mistakes.length})</button>` : '<p class="center c-rev"><b>Bezbłędnie! 🎯</b></p>'}</div>`;
}
function rulesHTML(st) {
  const o = st.opts || {};
  if (st.mode === 'mem') { const [n, t] = memNT(st); return `<p class="small muted">${n} elementów · ${t ? t + ' s na zapamiętanie' : 'bez limitu czasu'}${o.sab ? ' · sabotaże ✓' : ''}</p>`; }
  return `<p class="small muted">⏱ nauka: ${o.learnSec ? o.learnSec + ' s' : 'bez limitu'} · odpowiedź: ${o.ansSec ? o.ansSec + ' s' : 'bez limitu'} · sprawdzanie: ${{ strict: 'dokładne', normal: 'normalne', lenient: 'łagodne' }[o.tol] || 'normalne'}
    · wynik ${o.live === false ? 'ukryty do końca' : 'na żywo'} · sabotaże ${o.sab ? '✓' : '✗'}</p>`;
}
function battleTimer() {
  clearInterval(B.uiTimer);
  B.uiTimer = setInterval(() => {
    if (!B || (!$('#btimer') && !$('#cardleft'))) return clearInterval(B?.uiTimer);
    const o = B.setup.opts || {};
    if (B.phase === 'learn') {
      if (B.learnLimit) { const left = B.learnLimit - (Date.now() - B.learnStart); $('#btimer').textContent = fmtTime(Math.max(0, left)); if (left <= 0) beginRecall(); }
      else $('#btimer').textContent = fmtTime(Date.now() - B.learnStart);
    } else if (B.phase === 'recall') {
      if ($('#btimer')) $('#btimer').textContent = fmtTime(Date.now() - B.learnStart);
      if (B.frozenUntil > Date.now()) { B.cardStart += 300; const f = $('.freeze small'); if (f) f.textContent = Math.ceil((B.frozenUntil - Date.now()) / 1000) + ' s'; return; }
      if ($('.freeze')) renderBattle();
      if (o.ansSec) {
        const left = o.ansSec * 1000 - (Date.now() - B.cardStart);
        if ($('#cardleft')) $('#cardleft').textContent = `⏱ ${Math.ceil(Math.max(0, left) / 1000)} s`;
        if (left <= 0) submitAnswer($('#bt-in')?.value.trim() || '');
      }
    }
  }, 300);
}
// gra pamięciowa w bitwie: zakończenie memo i odtwarzania
on('gameRecallStart', () => { if (B && GAME?.battle) { B.myLearnMs = Date.now() - B.learnStart; B.ch?.send({ t: 'ready', ms: B.myLearnMs }); B.phase = 'recall'; } });
function battleMemFinish() {
  clearInterval(gameTimer);
  B.myMem = GAME.answer.map(v => GAME.d === 'numbers' ? v : v != null ? GAME.pool[v] : null);
  B.ch?.send({ t: 'mans', answers: B.myMem, ms: Date.now() - GAME.recallStart });
  myDone(); renderBattle();
}

// ============================================================ Ekran bitew (matchmaking + ustawienia)
ROUTES.battles = (parts, q) => {
  if (q.get('join')) { const code = q.get('join'); setTimeout(() => joinRoom(code), 30); }
  const bs = S.battles, w = bs.filter(b => b.won === 1).length, l = bs.filter(b => b.won === -1).length, d = bs.filter(b => b.won === 0).length;
  const heads = {}; bs.filter(b => !b.bot).forEach(b => { const h = heads[b.opp] || (heads[b.opp] = { w: 0, l: 0, d: 0, av: b.oppAvatar }); h[b.won === 1 ? 'w' : b.won === -1 ? 'l' : 'd']++; });
  const ms = memSettings(), o = btOpts(), mode = ms.btMode || 'cards';
  const sel = (id, list, cur) => `<select data-btopt="${id}">${list.map(([v, l]) => `<option value="${v}" ${String(cur) === String(v) ? 'selected' : ''}>${l}</option>`).join('')}</select>`;
  const memDisc = ms.btDisc || 'numbers';
  const deck = deckById(ms.btDeck) || S.decks[0];
  const summary = mode !== 'mem'
    ? `${mode === 'quiz' ? '🅰️ Quiz ABCD · ' : '📚 '}${esc(deck?.name || 'talia')} · ${o.n} fiszek · nauka ${o.learnSec ? o.learnSec / 60 + ' min' : '∞'} · odp. ${o.ansSec ? o.ansSec + ' s' : '∞'}${o.sab ? ' · sabotaże' : ''}`
    : `🧠 ${DISC[memDisc].name} · ${o.memN || MEM_DEFAULT[memDisc][0]} el. · ${o.memSec ? o.memSec + ' s' : 'bez limitu'}${o.sab ? ' · sabotaże' : ''}`;
  return { tab: 'battles', html: `
  <div class="row nowrap"><h1 class="grow">⚔️ Bitwy</h1>${coinsHTML()}</div>
  <div class="row nowrap elo-row">${eloHTML(myElo())}<span class="grow"></span></div>
  <p class="small muted">🏆 ${w} · 🤝 ${d} · 💪 ${l}${bs.length ? ` · ${Math.round(w / bs.length * 100)}% wygranych` : ''}</p>
  <button class="primary block big-btn" data-act="bt-quick">⚡ Szybki mecz</button>
  <p class="small muted center" style="margin:4px 0 12px">losowy przeciwnik · pojedynek pamięci</p>
  <div class="card">
    <div class="row"><button class="primary grow" data-act="bt-host">👥 Ze znajomym</button><button class="grow" data-act="bt-bot">🤖 Z botem</button></div>
    <div class="row nowrap" style="margin-top:10px"><input id="bt-code" class="grow" placeholder="Kod od znajomego" maxlength="6" autocapitalize="characters" style="text-transform:uppercase;letter-spacing:2px"><button data-act="bt-join">Dołącz</button></div>
  </div>
  <details class="card rules"${ms.rulesOpen ? ' open' : ''}><summary><b>⚙️ Zasady bitwy</b><div class="small muted">${summary}</div></summary>
    <div class="seg" style="display:flex;margin-top:10px"><button class="grow ${mode === 'cards' ? 'on' : ''}" data-act="bt-mode" data-m="cards">📚 Fiszki</button><button class="grow ${mode === 'quiz' ? 'on' : ''}" data-act="bt-mode" data-m="quiz">🅰️ ABCD</button><button class="grow ${mode === 'mem' ? 'on' : ''}" data-act="bt-mode" data-m="mem">🧠 Pamięć</button></div>
    ${mode === 'quiz' ? '<p class="small muted" style="margin:8px 0 0">Każde pytanie ma 4 odpowiedzi do wyboru – wygrywa ten, kto ma więcej poprawnych (przy remisie: szybszy).</p>' : ''}
    ${mode !== 'mem' ? `
      <label class="field"><span>Talia</span><select id="bt-deck">${S.decks.map(dk => `<option value="${dk.id}" ${deck?.id === dk.id ? 'selected' : ''}>${esc(dk.name)}</option>`).join('')}</select></label>
      <div class="grid2">
        <label class="field"><span>Liczba fiszek</span><input type="number" inputmode="numeric" min="3" max="50" data-btopt="n" value="${o.n}"></label>
        <label class="field"><span>Kierunek</span>${sel('dir', [['qa', 'pytanie → odp.'], ['aq', 'odp. → pytanie'], ['mix', 'mieszany']], o.dir)}</label>
        <label class="field"><span>Czas na naukę</span>${sel('learnSec', [[0, 'bez limitu'], [60, '1 min'], [120, '2 min'], [180, '3 min'], [300, '5 min'], [600, '10 min']], o.learnSec)}</label>
        <label class="field"><span>Czas na odpowiedź (tylko ABCD)</span>${sel('ansSec', [[0, 'bez limitu'], [10, '10 s'], [15, '15 s'], [25, '25 s'], [45, '45 s'], [60, '60 s']], o.ansSec)}</label>
        ${mode === 'quiz' ? '' : `<label class="field"><span>Sprawdzanie</span>${sel('tol', [['strict', 'dokładne'], ['normal', 'normalne'], ['lenient', 'łagodne']], o.tol)}</label>`}
        <label class="field"><span>Wynik rywala</span>${sel('live', [['1', 'na żywo'], ['0', 'ukryty do końca']], o.live ? '1' : '0')}</label>
      </div>`
      : `<div class="grid2">
        <label class="field"><span>Dyscyplina</span><select data-btopt="disc">${Object.keys(MEM_DEFAULT).map(k => `<option value="${k}" ${memDisc === k ? 'selected' : ''}>${DISC[k].icon} ${DISC[k].name}</option>`).join('')}</select></label>
        <label class="field"><span>Ile elementów</span><input type="number" inputmode="numeric" min="3" max="${MAX_ITEMS[memDisc]}" data-btopt="memN" value="${o.memN || MEM_DEFAULT[memDisc][0]}"></label>
        <label class="field"><span>Czas zapamiętywania</span>${sel('memSec', [[0, 'bez limitu'], [30, '30 s'], [60, '1 min'], [120, '2 min'], [180, '3 min'], [300, '5 min']], o.memSec)}</label>
      </div>`}
    <label class="field"><span>Poziom bota (bez wpływu na Elo)</span><select id="bt-botlvl">${BOT_LEVELS.map(([n, acc], i) => `<option value="${i}" ${(ms.botLevel ?? 0) === i ? 'selected' : ''}>${n}${acc ? ` (~${Math.round(acc * 100)}%)` : ` – jak Ty (~${Math.round(myBattleAccuracy() * 100)}%)`}</option>`).join('')}</select></label>
    <label class="check"><input type="checkbox" data-btopt="sab" ${o.sab ? 'checked' : ''}> Sabotaże za kryształy</label>
    ${o.sab ? `<div class="small muted">${Object.values(SABOTAGE).map(x => `${x.icon} ${x.name} (${x.cost}💎) – ${x.desc}`).join('<br>')}<br>Max ${SAB_MAX} na bitwę.</div>` : ''}
    <p class="small muted">Zasady ustala twórca pokoju. W teście nie da się wklejać, a wyjście z aplikacji kasuje bieżące pytanie.</p>
  </details>
  ${bs.length ? `<details class="card"><summary><b>📊 Historia</b> <span class="small muted">(${bs.length})</span></summary>
    ${Object.keys(heads).length ? `<h3>Bilans ze znajomymi</h3>${Object.entries(heads).map(([n, h]) => `<div class="kv"><span>${esc(h.av || '')} ${esc(n)}</span><b><span class="c-rev">${h.w}</span> : <span class="c-lrn">${h.l}</span>${h.d ? ` (${h.d} rem.)` : ''}</b></div>`).join('')}` : ''}
    <h3>Ostatnie bitwy</h3><p class="small muted" style="margin-top:-6px">Najedź albo stuknij, żeby zobaczyć szczegóły meczu.</p>
    ${bs.slice(-20).reverse().map(battleRowHTML).join('')}</details>` : ''}
  <div class="row"><button class="grow sm" data-go="#/shop">🛒 Sklep</button><button class="grow sm" data-go="#/theme">🎨 Motywy</button></div>` };
};
document.addEventListener('toggle', e => { if (e.target.classList?.contains('rules')) { memSettings().rulesOpen = e.target.open; save(); } }, true);
document.addEventListener('change', e => {
  const k = e.target.dataset?.btopt; if (!k) return;
  const ms = memSettings(); ms.bt = ms.bt || {};
  if (k === 'disc') { ms.btDisc = e.target.value; ms.bt.memN = 0; }
  else if (k === 'sab') ms.bt.sab = e.target.checked;
  else if (k === 'live') ms.bt.live = e.target.value === '1';
  else if (['n', 'learnSec', 'ansSec', 'memN', 'memSec'].includes(k)) ms.bt[k] = Math.max(0, +e.target.value || 0);
  else ms.bt[k] = e.target.value;
  save(); if (k === 'disc') render();
});
document.addEventListener('change', e => { if (e.target.id === 'bt-deck') { memSettings().btDeck = e.target.value; save(); } });

// Matchmaking: każdy szukający publikuje „seek” w poczekalni; gracz z większym id dołącza do pokoju drugiego.
function quickMatch() {
  newBattle({ role: 'seeker', phase: 'seeking', seekStart: Date.now() });
  const disc = ['numbers', 'words', 'images'][Math.random() * 3 | 0];
  B.code = roomCode(); B.setup = { mode: 'mem', disc, seed: Math.random() * 1e9 | 0, opts: { sab: true } };
  B.ch = channel('fiszki-room-' + B.code, onRoomMsg);
  const lobby = channel(LOBBY, m => {
    m = sBattleMsg(m); if (!m || !m.room || !m.from) return;
    if (!B || B.phase !== 'seeking' || m.t !== 'seek' || Date.now() - m.ts > 45000) return;
    if (MY_ID > m.from) { stopSeek(); B.ch.close(); B.lobby = null; joinRoom(m.room, true); }
  });
  B.lobby = lobby;
  const announce = () => { if (!B || B.phase !== 'seeking') return; lobby.send({ t: 'seek', room: B.code, ts: Date.now(), ...me() }); B.seekTimer = setTimeout(announce, 12000); };
  B.role = 'host'; announce(); B.phase = 'seeking';
  const refresh = setInterval(() => { if (!B || B.phase !== 'seeking') return clearInterval(refresh); renderBattle(); }, 5000);
  go('#/battle');
}
function stopSeek() { if (!B) return; clearTimeout(B.seekTimer); B.lobby?.close(); }
function startBot(setup, level) {
  const bp = botParams(level);
  newBattle({ role: 'bot', setup, botLevel: level, botP: bp, opp: { nick: `Bot ${bp.name.toLowerCase()}`, avatar: '🤖', level: Math.round(bp.acc * 20) } });
  startCountdown(); go('#/battle');
}
function friendSetup() {
  const ms = memSettings(), o = btOpts();
  if ((ms.btMode || 'cards') === 'mem') {
    const disc = ms.btDisc || 'numbers';
    return { mode: 'mem', disc, seed: Math.random() * 1e9 | 0, n: clamp(o.memN || MEM_DEFAULT[disc][0], 3, MAX_ITEMS[disc]), memo: o.memSec, opts: { sab: o.sab } };
  }
  const deckId = $('#bt-deck')?.value || (deckById(ms.btDeck) || S.decks[0])?.id;
  const abcd = ms.btMode === 'quiz';
  const cards = battleCards(deckId, clamp(o.n, 3, 50), o.dir, abcd);
  if (cards.length < 3) { toast('W tej talii jest za mało fiszek tekstowych (min. 3)'); return null; }
  if (abcd && cards.some(c => c.opts.length < 2)) { toast('Do quizu ABCD talia potrzebuje kilku różnych odpowiedzi'); return null; }
  return { mode: 'cards', deckId, deckName: deckById(deckId)?.name, cards, opts: { learnSec: o.learnSec, ansSec: abcd ? o.ansSec : 0, tol: o.tol, live: o.live, sab: o.sab, abcd } };
}

Object.assign(ACTIONS, {
  'bt-quick': () => quickMatch(),
  'bt-bot-now': () => { const st = B.setup; stopSeek(); B.ch?.close(); startBot(st, memSettings().botLevel ?? 0); },
  'bt-mode': el => { memSettings().btMode = el.dataset.m; save(); render(); },
  'bt-host': () => { const st = friendSetup(); if (st) hostRoom(st); },
  'bt-bot': () => { const st = friendSetup(); if (!st) return; const lv = $('#bt-botlvl') ? +$('#bt-botlvl').value : (memSettings().botLevel ?? 0); memSettings().botLevel = lv; save(); startBot(st, lv); },
  'bt-join': () => { const c = $('#bt-code').value.trim().toUpperCase(); if (c.length !== 6) return toast('Kod ma 6 znaków'); joinRoom(c); },
  'bt-quit': () => { if (B && B.phase !== 'end' && B.phase !== 'wait' && !confirm('Opuścić bitwę? Przeciwnik wygra walkowerem.')) return; quitBattle(); },
  'bt-ready': () => {
    const n = B.setup.cards?.length || 0;
    if (B.setup.mode === 'cards' && B.seen.size < n && !confirm(`Obejrzałeś ${B.seen.size} z ${n} fiszek. Przejść do testu?`)) return;
    beginRecall();
  },
  'bt-flip': () => { B.lflip = !B.lflip; render(); },
  'bt-lnav': el => { const n = B.setup.cards.length; B.li = (B.li + +el.dataset.d + n) % n; B.lflip = false; B.seen.add(B.li); render(); },
  'bt-submit': () => submitAnswer($('#bt-in').value.trim()),
  'bt-abcd': el => { const it = B?.setup?.cards[B.order[B.cur]]; if (it?.opts) submitAnswer(it.opts[+el.dataset.k]); },
  'bt-skip': () => submitAnswer(''),
  'bt-sab': el => { useSabotage(el.dataset.k); renderBattle(); },
  'bt-cram-mistakes': () => {
    // błędne fiszki z bitwy jako szybka nauka (bez harmonogramu): pytanie → odpowiedź
    const wrong = B.setup.cards.filter((_, i) => !B.myAns.find(a => a.i === i)?.ok);
    QUIZ = null; B.review = { list: shuffle([...wrong]), i: 0, shown: false }; render(); scrollTo(0, 0);
  },
  'bt-rv-show': () => { B.review.shown = true; render(); },
  'bt-rv-next': () => { B.review.i++; B.review.shown = false; render(); },
  'bt-rv-close': () => { B.review = null; render(); },
  'bt-rm': () => { if (!B || B.phase !== 'end') return; B.rmMine = true; B.ch?.send({ t: 'rm' }); maybeRematch(); renderBattle(); },
  'bt-new-opp': () => { const wasBot = B?.role === 'bot'; if (B) { if (B.phase !== 'end') B.ch?.send({ t: 'bye' }); else B.ch?.send({ t: 'bye' }); B.ch?.close(); (B.botTimers || []).forEach(clearTimeout); clearInterval(B.uiTimer); }
    B = null; GAME = null; void wasBot; quickMatch(); },
  'bt-walkover': () => { B.oppLeft = true; maybeFinish(); },
  'bt-rematch': () => { const st = B.setup; const lv = B.botLevel;
    const fresh = st.mode === 'mem' ? { ...st, seed: Math.random() * 1e9 | 0 } : { ...st, cards: shuffle([...st.cards]) }; startBot(fresh, lv); },
  'bt-share': async el => {
    const link = el.dataset.link, text = `⚔️ Wyzywam Cię na bitwę w Fiszkach! Kod: ${B.code}`;
    if (navigator.share) { try { await navigator.share({ title: 'Bitwa – Fiszki', text, url: link }); return; } catch (e) { if (e.name === 'AbortError') return; } }
    try { await navigator.clipboard.writeText(`${text}\n${link}`); toast('Skopiowano zaproszenie'); } catch { prompt('Skopiuj:', link); }
  },
  'bt-sticker': el => {
    if (Date.now() - lastSticker < 2500) return; lastSticker = Date.now();
    const shiny = shinyLv(el.dataset.k);
    B?.ch?.send({ t: 'st', k: el.dataset.k, shiny }); stickerFx(el.dataset.k, 'Ty', shiny);
    if (B?.role === 'bot' && Math.random() < .5) setTimeout(() => stickerFx(['wave', 'thumb', 'phew'][Math.random() * 3 | 0], B?.opp?.nick), 1200);
  },
  'bt-mic': () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition; if (!SR) return;
    if (speech) { speech.stop(); return; }
    speech = new SR(); speech.lang = 'pl-PL'; speech.interimResults = false; speech.maxAlternatives = 3;
    speech.onresult = e => { const alts = [...e.results[0]].map(r => r.transcript.trim()); const it = B.setup.cards[B.order[B.cur]];
      const best = alts.find(a => judge(a, it.a)) || alts[0]; const inp = $('#bt-in'); if (inp) inp.value = best; };
    speech.onend = () => { speech = null; renderBattle(); const v = $('#bt-in')?.value.trim(); if (v) submitAnswer(v); };
    speech.onerror = e => { toast('Mikrofon: ' + e.error); };
    speech.start(); render();
  },
});
;

/* ===== backup.js ===== */
'use strict';
/* Bezpieczeństwo danych:
   - codzienne kopie lokalne (ostatnie 14 dni) + kopia przed każdą ryzykowną operacją,
   - kosz: usunięte fiszki i talie można przywrócić przez 30 dni,
   - historia wersji w chmurze (każda synchronizacja z GitHub to osobna wersja),
   - pamięć trwała przeglądarki i przypomnienie, gdy dane nie są nigdzie zabezpieczone. */

var KEEP_SNAPSHOTS = 14, TRASH_DAYS = 30;
var SNAP_INDEX = [], TRASH = [], persisted = null;

async function snapshot(reason = 'codzienna') {
  const id = 'snap:' + Date.now();
  await DB.set(id, JSON.stringify({ ...S, settings: { ...S.settings, sync: { ...S.settings.sync, token: '' }, aiKey: '', geminiKey: '', hostToken: '' } }));
  SNAP_INDEX.push({ id, t: Date.now(), reason, cards: S.cards.length, notes: S.notes.length });
  SNAP_INDEX.sort((a, b) => a.t - b.t);
  // zostaw jedną kopię na dzień przez 14 dni + ostatnie 5 kopii „przed operacją”
  const keep = new Set(); const byDay = {};
  for (const s of SNAP_INDEX) if (s.reason === 'codzienna') byDay[dayKey(s.t)] = s.id;
  Object.keys(byDay).sort().slice(-KEEP_SNAPSHOTS).forEach(d => keep.add(byDay[d]));
  SNAP_INDEX.filter(s => s.reason !== 'codzienna').slice(-5).forEach(s => keep.add(s.id));
  for (const s of SNAP_INDEX) if (!keep.has(s.id)) await DB.del(s.id);
  SNAP_INDEX = SNAP_INDEX.filter(s => keep.has(s.id));
  await DB.set('snapIndex', SNAP_INDEX);
}
on('start', async () => {
  SNAP_INDEX = (await DB.get('snapIndex')) || [];
  TRASH = ((await DB.get('trash')) || []).filter(x => Date.now() - x.t < TRASH_DAYS * DAY);
  const last = SNAP_INDEX.filter(s => s.reason === 'codzienna').pop();
  if (!last || dayKey(last.t) !== dayKey(Date.now())) snapshot('codzienna');
  try { persisted = await navigator.storage?.persisted?.(); if (!persisted) persisted = await navigator.storage?.persist?.(); } catch { /* */ }
});

// --- kosz: zapis kopii przed usunięciem
on('deleting', (kind, data) => {
  TRASH.push({ id: uid(), t: Date.now(), kind, data: structuredClone(data) });
  DB.set('trash', TRASH);
});
function restoreTrash(entry) {
  if (entry.kind === 'atlas') S.atlases.push(touch({ ...structuredClone(entry.data.atlas), id: uid() }));
  else if (entry.kind === 'deck') {
    let d = S.decks.find(x => x.name === entry.data.deck.name);
    if (!d) d = newDeck(entry.data.deck.name);
    for (const n of entry.data.notes) restoreNote(n.note, n.cards, d.id);
  } else restoreNote(entry.data.note, entry.data.cards);
  TRASH = TRASH.filter(x => x !== entry); DB.set('trash', TRASH); save();
}
// przywracamy z nowymi identyfikatorami (stare są oznaczone jako usunięte także na innych urządzeniach)
function restoreNote(note, cards, deckId) {
  const did = deckId || (deckById(note.deckId) ? note.deckId : (S.decks.find(x => x.name === 'Przywrócone') || newDeck('Przywrócone')).id);
  const nn = touch({ ...structuredClone(note), id: uid(), deckId: did });
  S.notes.push(nn);
  for (const c of cards) S.cards.push(touch({ ...structuredClone(c), id: uid(), noteId: nn.id, deckId: did }));
  syncCards(nn);
}
var trashLabel = e => e.kind === 'atlas' ? `🫀 Rycina „${e.data.atlas.name}”` : e.kind === 'deck' ? `📦 Talia „${e.data.deck.name}” (${e.data.notes.length} fiszek)`
  : `🃏 ${e.data.note.type === 'cloze' ? clozePlain(e.data.note.text) : e.data.note.type === 'occl' ? (e.data.note.title || 'Obraz z lukami') : e.data.note.front}`;

function safetyStatus() {
  const cloud = !!S.settings.sync.token && S.settings.lastSync && Date.now() - S.settings.lastSync < 7 * DAY;
  const exported = S.settings.lastExport && Date.now() - S.settings.lastExport < 14 * DAY;
  return { cloud, exported, safe: cloud || exported };
}
function safetyBannerHTML() {
  if (S.cards.length < 15 || safetyStatus().safe) return '';
  if (S.settings.safetySnooze && Date.now() - S.settings.safetySnooze < 3 * DAY) return '';
  return `<div class="banner warn row nowrap"><span class="grow">🛡️ <b>Zabezpiecz swoje fiszki</b> – są tylko na tym urządzeniu. Włącz synchronizację z chmurą albo pobierz kopię.</span>
    <button class="sm primary" data-go="#/safety">Zabezpiecz</button><button class="sm ghost" data-act="safety-snooze">✕</button></div>`;
}

ROUTES.safety = () => {
  const st = safetyStatus();
  const snaps = SNAP_INDEX.slice().reverse();
  const isStandalone = matchMedia('(display-mode: standalone)').matches || navigator.standalone;
  if (S.settings.sync.token && S.settings.sync.gistId && !CLOUD_VERS.loaded) loadCloudVersions();
  return { tab: 'more', html: `
  <div class="row nowrap"><button class="iconbtn" data-go="#/more">‹</button><h1 class="grow">Bezpieczeństwo danych</h1></div>
  <div class="card">
    <div class="kv"><span>☁️ Kopia w chmurze (GitHub)</span><b class="${st.cloud ? 'c-rev' : 'c-lrn'}">${S.settings.sync.token ? (st.cloud ? '✓ ' + ago(S.settings.lastSync) : '⚠️ dawno') : '✗ wyłączona'}</b></div>
    <div class="kv"><span>📁 Kopia w pliku</span><b>${S.settings.lastExport ? ago(S.settings.lastExport) : 'nigdy'}</b></div>
    <div class="kv"><span>💾 Kopie lokalne</span><b>${SNAP_INDEX.length}</b></div>
    <div class="kv"><span>🗑️ Kosz</span><b>${TRASH.length}</b></div>
    <div class="kv"><span>🔒 Pamięć trwała</span><b>${persisted ? '✓ włączona' : isStandalone ? '✓ aplikacja' : '⚠️ dodaj do ekranu głównego'}</b></div>
  </div>
  <div class="card small"><b>Jak nie stracić fiszek?</b><ol class="steps">
    <li><b>Dodaj aplikację do ekranu początkowego</b> – Safari może czyścić dane stron nieużywanych przez 7 dni, ale nie robi tego zainstalowanym aplikacjom.</li>
    <li><b>Włącz synchronizację z GitHub</b> (Więcej → Telefon ⇄ komputer) – fiszki są wtedy w Twojej prywatnej chmurze, a każda synchronizacja to wersja, do której możesz wrócić.</li>
    <li>Od czasu do czasu <b>pobierz kopię do pliku</b> (np. do iCloud Drive).</li></ol>
    <div class="row"><button class="primary grow" data-act="export">⬇️ Pobierz kopię teraz</button>${S.settings.sync.token ? '<button class="grow" data-act="sync">🔄 Synchronizuj</button>' : '<button class="grow" data-go="#/more">☁️ Włącz chmurę</button>'}</div></div>
  <div class="card"><h2 style="margin-top:0">🗑️ Kosz</h2><p class="small muted">Usunięte fiszki i talie z ostatnich ${TRASH_DAYS} dni.</p>
    ${TRASH.slice().reverse().map(e => `<div class="kv"><span class="grow" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(trashLabel(e))}<br><small class="muted">${ago(e.t)}</small></span>
      <button class="sm" data-act="trash-restore" data-id="${e.id}">↺ Przywróć</button></div>`).join('') || '<p class="muted small">Kosz jest pusty.</p>'}</div>
  <div class="card"><h2 style="margin-top:0">💾 Kopie na tym urządzeniu</h2><p class="small muted">Robione automatycznie codziennie i przed ryzykownymi operacjami.</p>
    ${snaps.map(s => `<div class="kv"><span>${new Date(s.t).toLocaleString('pl', { dateStyle: 'medium', timeStyle: 'short' })}<br><small class="muted">${esc(s.reason)} · ${s.cards} kart</small></span>
      <button class="sm" data-act="snap-restore" data-id="${s.id}">↺ Przywróć</button></div>`).join('') || '<p class="muted small">Brak kopii.</p>'}
    <button class="sm block" data-act="snap-now">➕ Zrób kopię teraz</button></div>
  ${S.settings.sync.gistId ? `<div class="card"><h2 style="margin-top:0">☁️ Wersje w chmurze</h2>
    ${CLOUD_VERS.list.map(v => `<div class="kv"><span>${new Date(v.t).toLocaleString('pl', { dateStyle: 'medium', timeStyle: 'short' })}</span><button class="sm" data-act="cloud-restore" data-v="${v.v}">↺ Przywróć</button></div>`).join('') || `<p class="muted small">${CLOUD_VERS.loading ? 'Wczytuję…' : 'Brak wersji.'}</p>`}</div>` : ''}` };
};
var CLOUD_VERS = { list: [], loaded: false, loading: false };
async function loadCloudVersions() {
  CLOUD_VERS.loaded = true; CLOUD_VERS.loading = true;
  try {
    const g = await gh('/gists/' + S.settings.sync.gistId);
    CLOUD_VERS.list = (g.history || []).slice(0, 20).map(h => ({ v: h.version, t: new Date(h.committed_at).getTime() }));
  } catch (e) { toast('Nie udało się wczytać wersji: ' + e.message); }
  CLOUD_VERS.loading = false; if (parseRoute().parts[0] === 'safety') render();
}
async function replaceState(data, label) {
  await snapshot('przed przywróceniem');
  if (typeof econLocked === 'function' && econLocked()) { econGuard(data, true); toast('Kryształy i przedmioty zostają obecne – kopia ich nie przywraca (blokada od twórcy aplikacji)', 4500); }
  const keepSettings = S.settings;
  S = { ...blankState(), ...data, settings: keepSettings };
  for (const [k, v] of Object.entries(extraState())) if (S[k] == null) S[k] = v;
  // przywrócone dane muszą „wygrać” z synchronizacją – oznaczamy je jako najnowsze
  const now = Date.now();
  for (const key of ['decks', 'notes', 'cards', 'palaces', 'topics', 'friends']) (S[key] || []).forEach(x => { x.mod = now; delete S.tomb[x.id]; });
  await DB.set('state', S); toast(`Przywrócono: ${label} ✓`, 3500); go('#/'); render();
}

Object.assign(ACTIONS, {
  'safety-snooze': () => { S.settings.safetySnooze = Date.now(); save(); render(); },
  'trash-restore': el => { const e = TRASH.find(x => x.id === el.dataset.id); if (e) { restoreTrash(e); toast('Przywrócono ✓'); render(); } },
  'snap-now': async () => { await snapshot('ręczna'); toast('Kopia zapisana ✓'); render(); },
  'snap-restore': async el => {
    const s = SNAP_INDEX.find(x => x.id === el.dataset.id); if (!s) return;
    if (!confirm(`Przywrócić stan z ${new Date(s.t).toLocaleString('pl')}? Obecny stan zostanie zapisany jako kopia.`)) return;
    const raw = await DB.get(s.id); if (!raw) return toast('Kopia niedostępna');
    replaceState(JSON.parse(raw), 'kopia lokalna');
  },
  'cloud-restore': async el => {
    if (!confirm('Przywrócić tę wersję z chmury? Obecny stan zostanie zapisany jako kopia lokalna.')) return;
    try {
      const g = await gh(`/gists/${S.settings.sync.gistId}/${el.dataset.v}`);
      const f = g.files['data.json']; if (!f) throw new Error('brak danych w tej wersji');
      replaceState(JSON.parse(await gistText(f)), 'wersja z chmury');
    } catch (e) { toast('Błąd: ' + e.message, 4000); }
  },
});
;

/* ===== stickies.js ===== */
'use strict';
/* Karteczki-przypominajki (żółte „post-it”) na ekranie startowym.
   Można ustawić termin, kolor, odhaczyć – i zapisać wszystkie jako obraz na tapetę / ekran blokady telefonu. */

var STICKY_COLORS = { y: '#fde68a', p: '#fbcfe8', g: '#bbf7d0', b: '#bfdbfe', o: '#fed7aa' };
var stickyById = id => S.stickies.find(x => x.id === id);
// kolor: jeden z gotowych albo własny (#rrggbb); tekst ciemny lub jasny – zależnie od tła
var stickyColor = s => STICKY_COLORS[s.color] || (/^#[0-9a-f]{6}$/i.test(s.color || '') ? s.color : STICKY_COLORS.y);
var stickyInk = s => { try { return lum(stickyColor(s)) < .28 ? '#f8fafc' : '#1f2937'; } catch { return '#1f2937'; } };
var stickyVars = (s, rot) => `--sc:${stickyColor(s)};--ink:${stickyInk(s)};--rot:${rot}deg`;
// komputer (szeroki ekran + mysz): karteczki można przypiąć w dowolnym miejscu ekranu głównego
var stickyDesk = () => matchMedia('(min-width: 900px) and (pointer: fine)').matches;
var activeStickies = () => S.stickies.filter(x => !x.done).sort((a, b) => (a.due || 9e15) - (b.due || 9e15) || a.created - b.created);
function dueLabel(t) {
  if (!t) return '';
  const d = Math.round((dayStart(t) - dayStart()) / DAY);
  return d < 0 ? `⚠️ ${-d} ${plural(-d, 'dzień', 'dni', 'dni')} temu` : d === 0 ? '⏰ dziś' : d === 1 ? 'jutro' : new Date(t).toLocaleDateString('pl', { day: 'numeric', month: 'short' });
}
function stickiesHTML() {
  const all = activeStickies(), desk = stickyDesk();
  const list = desk ? all.filter(x => !x.pin) : all, pinned = desk ? all.filter(x => x.pin) : [];
  const due = s => s.due ? `<span class="due${s.due < dayStart() ? ' late' : ''}">${dueLabel(s.due)}</span>` : '';
  const card = (s, i) => `<div class="sticky" style="${stickyVars(s, [-2, 1.5, -1, 2.2, -1.6][i % 5])}">
        <div class="stxt" data-go="#/sticky/${s.id}">${fmt(s.text)}</div>
        <div class="row nowrap small">${due(s)}<span class="grow"></span>
          ${desk ? `<button class="ghost sm" data-act="sticky-pin" data-id="${s.id}" title="Przypnij w dowolnym miejscu ekranu">📍</button>` : ''}
          <button class="ghost sm" data-act="sticky-done" data-id="${s.id}" title="Zrobione">✓</button></div></div>`;
  const free = s => `<div class="sticky free" data-id="${s.id}" style="${stickyVars(s, 0)};left:${(s.pin.x * 100).toFixed(2)}vw;top:${(s.pin.y * 100).toFixed(2)}vh">
        <div class="grip" title="Przeciągnij, żeby przesunąć">⠿</div>
        <div class="stxt" data-go="#/sticky/${s.id}">${fmt(s.text)}</div>
        <div class="row nowrap small">${due(s)}<span class="grow"></span>
          <button class="ghost sm" data-act="sticky-unpin" data-id="${s.id}" title="Odepnij (wróć do listy)">↩</button>
          <button class="ghost sm" data-act="sticky-done" data-id="${s.id}" title="Zrobione">✓</button></div></div>`;
  if (pinned.length) onMount(mountStickyDrag);
  return `<div class="stickies-wrap"><div class="row nowrap"><b class="grow">📌 Karteczki</b>
      ${all.length ? '<button class="sm ghost" data-act="sticky-wall">🖼️ Tapeta</button>' : ''}<button class="sm" data-act="sticky-new">➕</button></div>
    ${list.length ? `<div class="stickies">${list.map(card).join('')}</div>`
    : pinned.length ? '<p class="small muted" style="margin:4px 0 0">Wszystkie karteczki są przypięte na ekranie – przeciągaj je za ⠿.</p>'
    : `<p class="small muted" style="margin:4px 0 0">Przyklej sobie przypomnienie – np. „powtórzyć nerwy czaszkowe przed piątkiem”.${desk ? ' Na komputerze możesz je przypiąć w dowolnym miejscu (📍).' : ''}</p>`}</div>
    ${pinned.length ? `<div class="sticky-layer">${pinned.map(free).join('')}</div>` : ''}`;
}
// przeciąganie przypiętych karteczek (pozycja w % okna – pasuje do każdego rozmiaru)
function mountStickyDrag() {
  document.querySelectorAll('.sticky.free .grip').forEach(g => g.addEventListener('pointerdown', e => {
    const el = g.closest('.sticky.free'), s = stickyById(el.dataset.id); if (!s) return;
    e.preventDefault(); g.setPointerCapture(e.pointerId); el.classList.add('dragging');
    const r = el.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;
    const move = ev => {
      const x = clamp(ev.clientX - dx, 0, innerWidth - r.width), y = clamp(ev.clientY - dy, 0, innerHeight - 40);
      el.style.left = x + 'px'; el.style.top = y + 'px';
    };
    const up = () => {
      g.removeEventListener('pointermove', move); g.removeEventListener('pointerup', up); g.removeEventListener('pointercancel', up);
      el.classList.remove('dragging');
      const nr = el.getBoundingClientRect();
      s.pin = { x: +(nr.left / innerWidth).toFixed(4), y: +(nr.top / innerHeight).toFixed(4) }; touch(s); save();
    };
    g.addEventListener('pointermove', move); g.addEventListener('pointerup', up); g.addEventListener('pointercancel', up);
  }));
}
ROUTES.sticky = parts => {
  const s = stickyById(parts[1]);
  if (!s) return { html: '<p><a href="#/">Wróć</a></p>' };
  onMount(() => {
    const ta = $('#st-text'); ta.focus();
    ta.addEventListener('input', () => { s.text = ta.value; touch(s); save(); });
    const col = $('#st-color');
    col.addEventListener('input', () => { s.color = col.value; $('#st-big').setAttribute('style', stickyVars(s, 0)); col.parentElement.style.background = col.value; });
    col.addEventListener('change', () => { s.color = col.value; touch(s); save(); render(); });
    $('#st-due').addEventListener('change', e => { s.due = e.target.value ? new Date(e.target.value + 'T09:00').getTime() : null; touch(s); save(); });
  });
  const dueVal = s.due ? new Date(s.due).toISOString().slice(0, 10) : '';
  return { tab: 'home', html: `<div class="row nowrap"><button class="iconbtn" data-go="#/">‹</button><h1 class="grow">Karteczka</h1></div>
    <div class="sticky big" id="st-big" style="${stickyVars(s, 0)}"><textarea id="st-text" rows="6" placeholder="Co mam zapamiętać / zrobić?">${esc(s.text)}</textarea></div>
    <div class="row">${Object.entries(STICKY_COLORS).map(([k, c]) => `<button class="swatch${s.color === k ? ' on' : ''}" style="background:${c};width:44px" data-act="sticky-color" data-id="${s.id}" data-c="${k}"></button>`).join('')}
      <label class="swatch custom-col${STICKY_COLORS[s.color] ? '' : ' on'}" title="Własny kolor" style="background:${STICKY_COLORS[s.color] ? 'conic-gradient(#f87171,#facc15,#4ade80,#60a5fa,#c084fc,#f87171)' : stickyColor(s)}">
        <input type="color" id="st-color" value="${stickyColor(s)}"></label></div>
    <p class="small muted" style="margin:4px 0 0">🎨 Ostatnie pole to dowolny własny kolor.${stickyDesk() ? ' Na ekranie głównym możesz przypiąć karteczkę w dowolnym miejscu (📍).' : ''}</p>
    <label class="field"><span>Termin (opcjonalnie)</span><input type="date" id="st-due" value="${dueVal}"></label>
    <div class="row"><button class="primary grow" data-go="#/">Gotowe</button><button class="danger" data-act="sticky-del" data-id="${s.id}">Usuń</button></div>` };
};

// Tapeta: wszystkie karteczki jako obraz (do ustawienia jako tło / ekran blokady)
async function stickyWallpaper() {
  const W = 1170, H = 2532, c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  const bg = g.createLinearGradient(0, 0, W, H); bg.addColorStop(0, '#1e1b4b'); bg.addColorStop(1, '#0f172a');
  g.fillStyle = bg; g.fillRect(0, 0, W, H);
  const list = activeStickies().slice(0, 8), cols = 2, pad = 70, nw = (W - pad * 3) / 2, nh = 440, top = 820;  // zostawiamy miejsce na zegar
  g.textBaseline = 'top';
  list.forEach((s, i) => {
    const x = pad + (i % cols) * (nw + pad), y = top + Math.floor(i / cols) * (nh + 60);
    g.save(); g.translate(x + nw / 2, y + nh / 2); g.rotate([-2, 1.5, -1, 2.2][i % 4] * Math.PI / 180); g.translate(-nw / 2, -nh / 2);
    g.shadowColor = 'rgba(0,0,0,.45)'; g.shadowBlur = 30; g.shadowOffsetY = 14;
    g.fillStyle = stickyColor(s); g.fillRect(0, 0, nw, nh); g.shadowColor = 'transparent';
    g.fillStyle = 'rgba(0,0,0,.08)'; g.fillRect(0, 0, nw, 46);
    g.fillStyle = stickyInk(s); g.font = '600 46px -apple-system, Segoe UI, sans-serif';
    const words = s.text.replace(/\n/g, ' \n ').split(' '); let line = '', ly = 76;
    for (const w of words) {
      if (w === '\n' || g.measureText(line + w).width > nw - 60) { g.fillText(line, 30, ly); ly += 58; line = w === '\n' ? '' : w + ' '; if (ly > nh - 110) break; }
      else line += w + ' ';
    }
    if (ly <= nh - 110) g.fillText(line, 30, ly);
    if (s.due) { g.font = '700 38px -apple-system, sans-serif'; g.fillStyle = s.due < dayStart() ? '#b91c1c' : '#92400e'; g.fillText(dueLabel(s.due), 30, nh - 70); }
    g.restore();
  });
  const blob = await new Promise(r => c.toBlob(r, 'image/png'));
  await shareOrDownload(blob, 'karteczki-tapeta.png');
  toast('Zapisz obraz i ustaw jako tapetę lub ekran blokady (Zdjęcia → Udostępnij → Użyj jako tapety)', 5000);
}

Object.assign(ACTIONS, {
  'sticky-new': () => { const s = touch({ id: uid(), text: '', color: 'y', due: null, done: false, created: Date.now() }); S.stickies.push(s); save(); go('#/sticky/' + s.id); },
  'sticky-done': el => { const s = stickyById(el.dataset.id); if (s) { s.done = true; touch(s); save(); render(); toast('✓ Odhaczone'); } },
  'sticky-del': el => { S.stickies = S.stickies.filter(x => x.id !== el.dataset.id); S.tomb[el.dataset.id] = Date.now(); save(); go('#/'); },
  'sticky-color': el => { const s = stickyById(el.dataset.id); s.color = el.dataset.c; touch(s); save(); render(); },
  'sticky-wall': () => stickyWallpaper(),
  'sticky-pin': el => {
    const s = stickyById(el.dataset.id); if (!s) return;
    const n = S.stickies.filter(x => x.pin && !x.done).length;   // kolejne lądują obok siebie po prawej
    s.pin = { x: clamp(.74 - (n % 3) * .05, .02, .85), y: clamp(.12 + (n % 5) * .1, .02, .8) }; touch(s); save(); render();
    toast('Przypięte 📍 – przeciągnij za ⠿ w dowolne miejsce');
  },
  'sticky-unpin': el => { const s = stickyById(el.dataset.id); if (s) { delete s.pin; touch(s); save(); render(); } },
});
// puste karteczki nie zostają po wyjściu z edycji
window.addEventListener('hashchange', () => {
  if (!S || parseRoute().parts[0] === 'sticky') return;
  const empty = S.stickies.filter(x => !x.text.trim());
  if (empty.length) { empty.forEach(x => { S.tomb[x.id] = Date.now(); }); S.stickies = S.stickies.filter(x => x.text.trim()); save(); }
});
;

/* ===== anatomy.js ===== */
'use strict';
/* Atlas – tryb nauki anatomii (i każdych innych rycin): dodajesz własne zdjęcie, zaznaczasz struktury pinezkami
   i wpisujesz ich nazwy. Potem trzy tryby:
   – Przegląd: stukasz w pinezki i odkrywasz nazwy,
   – Nazywanie: podświetla się struktura, wpisujesz (albo mówisz) jej nazwę,
   – Wskazywanie: widzisz nazwę, stukasz w obrazie, gdzie to jest.
   Z atlasu można też zrobić fiszki (z powtórkami). */

var atlasById = id => (S.atlases || []).find(a => a.id === id);
var AT = null;   // stan bieżącej sesji atlasu

ROUTES.atlas = parts => {
  if (!parts[1]) return atlasList();
  const a = atlasById(parts[1]);
  if (!a) return { html: '<p>Nie ma takiego atlasu. <a href="#/atlas">Wróć</a></p>', tab: 'topics' };
  if (!AT || AT.id !== a.id) AT = { id: a.id, mode: a.marks.length ? 'review' : 'edit', shown: new Set(), sel: null };
  const modes = [['review', '👁️ Przegląd'], ['name', '✍️ Nazwij'], ['point', '👆 Wskaż'], ['draw', '🎨 Rysuj'], ['edit', '✏️ Edycja']];
  const head = `<div class="row nowrap"><button class="iconbtn" data-act="atlas-back">‹</button><h1 class="grow" style="font-size:21px">🫀 ${esc(a.name)}</h1>
      <button class="iconbtn" data-act="atlas-rename" data-id="${a.id}">✏️</button><button class="iconbtn" data-act="atlas-del" data-id="${a.id}" title="Usuń rycinę">🗑️</button></div>
    <div class="atmodes">${modes.map(([m, l]) => { const [ic, ...t] = l.split(' '); return `<button class="${AT.mode === m ? 'on' : ''}" data-act="atlas-mode" data-m="${m}" ${!['edit', 'draw'].includes(m) && !a.marks.length ? 'disabled' : ''}><span>${ic}</span><small>${t.join(' ')}</small></button>`; }).join('')}</div>`;
  let body = '';
  if (AT.mode === 'edit') { onMount(() => mountAtlasEditor(a)); body = atlasEdit(a); }
  else if (AT.mode === 'review') body = atlasReview(a);
  else if (AT.mode === 'draw') body = atlasDraw(a);
  else body = atlasQuiz(a);
  return { tab: 'topics', focus: ['name', 'point', 'draw'].includes(AT.mode), html: head + body };
};

function atlasList() {
  const list = (S.atlases || []).map(a => `<div class="note"><span data-go="#/atlas/${a.id}">${IMG[a.imageId] ? `<img src="${IMG[a.imageId]}" alt="">` : '<span style="font-size:30px">🫀</span>'}</span>
    <div class="t" data-go="#/atlas/${a.id}"><div><b>${esc(a.name)}</b></div><div class="small muted">${a.marks.length} ${plural(a.marks.length, 'struktura', 'struktury', 'struktur')}${a.best != null ? ` · najlepszy wynik ${a.best}%` : ''}</div></div>
    <button class="iconbtn" data-act="atlas-del" data-id="${a.id}" title="Usuń rycinę" aria-label="Usuń rycinę">🗑️</button></div>`).join('');
  return { tab: 'topics', html: `<div class="row nowrap"><button class="iconbtn" data-go="#/topics">‹</button><h1 class="grow">🫀 Atlas</h1></div>
    <div class="card small muted" style="margin-top:0">Dodaj własną rycinę (np. ze skryptu, atlasu albo zdjęcie preparatu), zaznacz struktury i ucz się je nazywać i wskazywać.</div>
    <div class="card">${list || '<p class="muted">Nie masz jeszcze żadnej ryciny.</p>'}
      <div class="spacer"></div><div class="row"><button class="primary grow" data-act="atlas-new" data-src="file">🖼️ Dodaj zdjęcie</button><button class="grow" data-act="atlas-new" data-src="paste">📋 Wklej</button></div></div>` };
}

// ---------- Edycja: pinezki z nazwami
function atlasEdit(a) {
  return `<p class="small muted">Stuknij w obraz, aby zaznaczyć strukturę. Przeciągnij pinezkę, aby ją przesunąć.</p>
    <div class="editor-wrap"><div class="occl stage" id="stage"><img src="${IMG[a.imageId] || ''}" alt=""><div id="stage-boxes"></div></div></div>
    <div id="marklist"></div>
    <div class="spacer"></div>
    <div class="row"><button class="grow" data-act="atlas-cards" data-id="${a.id}" ${a.marks.length ? '' : 'disabled'}>🃏 Zrób fiszki z powtórkami</button>
      <button class="danger" data-act="atlas-del" data-id="${a.id}">Usuń atlas</button></div>`;
}
function mountAtlasEditor(a) {
  const stage = $('#stage'); if (!stage) return;
  const commit = () => { touch(a); save(); $$('[data-act=atlas-mode]').forEach(b => { if (!['edit', 'draw'].includes(b.dataset.m)) b.disabled = !a.marks.length; }); };
  const draw = () => { $('#stage-boxes').innerHTML = a.marks.map((m, i) => `<div class="pin${AT.sel === m.id ? ' sel' : ''}" data-id="${m.id}" style="left:${m.x * 100}%;top:${m.y * 100}%">${i + 1}</div>`).join(''); };
  const list = () => {
    $('#marklist').innerHTML = a.marks.length ? `<h3>Struktury (${a.marks.length})</h3>` + a.marks.map((m, i) => `
      <div class="boxrow${AT.sel === m.id ? ' sel' : ''}"><span class="num">${i + 1}</span>
        <input data-mark="${m.id}" data-f="name" value="${esc(m.name)}" placeholder="Nazwa (np. m. biceps brachii)">
        <input data-mark="${m.id}" data-f="hint" value="${esc(m.hint || '')}" placeholder="💡 Skojarzenie">
        <button class="danger sm" data-act="atlas-mark-del" data-id="${m.id}">✕</button></div>`).join('')
      : '<p class="muted small center">Brak struktur – stuknij w obraz.</p>';
    $$('[data-mark]').forEach(inp => inp.addEventListener('input', () => { const m = a.marks.find(x => x.id === inp.dataset.mark); if (m) { m[inp.dataset.f] = inp.value; commit(); } }));
  };
  const rel = e => { const r = stage.getBoundingClientRect(); return { x: clamp((e.clientX - r.left) / r.width, 0, 1), y: clamp((e.clientY - r.top) / r.height, 0, 1) }; };
  let drag = null;
  stage.addEventListener('pointerdown', e => {
    e.preventDefault();
    const hit = e.target.closest('.pin');
    if (hit) { drag = { m: a.marks.find(x => x.id === hit.dataset.id), moved: false }; AT.sel = drag.m.id; stage.setPointerCapture(e.pointerId); draw(); list(); }
    else { const p = rel(e), m = { id: uid(), x: p.x, y: p.y, name: '', hint: '' }; a.marks.push(m); AT.sel = m.id; commit(); draw(); list();
      setTimeout(() => $(`[data-mark="${m.id}"][data-f="name"]`)?.focus(), 30); }
  });
  stage.addEventListener('pointermove', e => { if (!drag) return; const p = rel(e); drag.m.x = p.x; drag.m.y = p.y; drag.moved = true; draw(); });
  const end = () => { if (drag?.moved) commit(); drag = null; };
  stage.addEventListener('pointerup', end); stage.addEventListener('pointercancel', end);
  draw(); list();
}

// ---------- Przegląd
function atlasReview(a) {
  const all = AT.shown.size === a.marks.length;
  return `<p class="small muted">Stuknij pinezkę, żeby zobaczyć nazwę.</p>
    <div class="atlas-view"><div class="occl"><img src="${IMG[a.imageId] || ''}" alt="">
      ${a.marks.map((m, i) => `<div class="pin${AT.shown.has(m.id) ? ' rev' : ''}" data-act="atlas-reveal" data-id="${m.id}" style="left:${m.x * 100}%;top:${m.y * 100}%">${i + 1}</div>
        ${AT.shown.has(m.id) ? `<div class="pinlabel" style="left:${m.x * 100}%;top:${m.y * 100}%">${esc(m.name || '?')}</div>` : ''}`).join('')}</div></div>
    <div class="row"><button class="grow" data-act="atlas-all">${all ? '🙈 Ukryj wszystkie' : '👁️ Pokaż wszystkie'}</button></div>
    <div class="card tight">${a.marks.map((m, i) => `<div class="kv"><span>${i + 1}.</span><span class="grow" style="margin-left:8px">${AT.shown.has(m.id) ? esc(m.name) : '<span class="muted">• • •</span>'}</span></div>`).join('')}</div>`;
}

// ---------- Quiz: nazywanie i wskazywanie
function startAtlasQuiz(a, mode) {
  AT.mode = mode; AT.q = shuffle(a.marks.filter(m => m.name.trim()).map(m => m.id)); AT.i = 0; AT.res = []; AT.ans = null; AT.tap = null; AT.t0 = Date.now();
}
function atlasQuiz(a) {
  if (!AT.q) startAtlasQuiz(a, AT.mode);
  if (!AT.q.length) return '<p class="muted">Nadaj strukturom nazwy w trybie Edycja.</p>';
  if (AT.i >= AT.q.length) {
    const ok = AT.res.filter(r => r.ok).length, pct = Math.round(ok / AT.q.length * 100);
    if (!AT.saved) { AT.saved = true; if (pct > (a.best ?? -1)) { a.best = pct; touch(a); } S.stats.atlasRuns = (S.stats.atlasRuns || 0) + 1; save(); }
    return `<div class="card center"><div class="score">${pct}%</div><p>${ok} / ${AT.q.length} poprawnie · ${fmtTime(Date.now() - AT.t0)}</p></div>
      <div class="card">${AT.res.map(r => { const m = a.marks.find(x => x.id === r.id); return `<div class="kv"><span>${r.ok ? '✅' : '❌'} ${esc(m?.name || '')}</span>${r.ok ? '' : `<small class="muted">${esc(r.given || '–')}</small>`}</div>`; }).join('')}</div>
      <div class="row"><button class="primary grow" data-act="atlas-again">🔁 Jeszcze raz</button>${AT.res.some(r => !r.ok) ? '<button class="grow" data-act="atlas-wrong">Powtórz błędne</button>' : ''}</div>`;
  }
  const m = a.marks.find(x => x.id === AT.q[AT.i]), idx = a.marks.indexOf(m);
  const prog = `<div class="row small muted"><span class="grow">${AT.i + 1} / ${AT.q.length}</span><span>✅ ${AT.res.filter(r => r.ok).length}</span></div>${progress(AT.i / AT.q.length, true)}`;
  if (AT.mode === 'name') {
    const answered = AT.ans != null;
    if (!answered) onMount(() => { const inp = $('#at-in'); inp.focus({ preventScroll: true }); inp.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); ACTIONS['atlas-check'](); } }); });
    return prog + `<div class="atlas-view"><div class="occl"><img src="${IMG[a.imageId] || ''}" alt="">
        ${a.marks.map((x, i) => `<div class="pin ${x.id === m.id ? (answered ? 'rev' : 'target') : 'dim'}" style="left:${x.x * 100}%;top:${x.y * 100}%">${x.id === m.id && !answered ? '?' : i + 1}</div>`).join('')}</div></div>
      ${answered ? `<div class="card center"><div class="ansline">${esc(m.name)}</div>${AT.ans.ok ? '✅ Dobrze' : `❌ Twoja odpowiedź: <b>${esc(AT.ans.given || '–')}</b>`}
          ${!AT.ans.ok ? '<br><button class="ghost sm" data-act="atlas-override">To była dobra odpowiedź</button>' : ''}</div>
          <button class="primary block" data-act="atlas-next">Dalej ›</button>`
        : `${m.hint && AT.hint ? `<div class="hintbox">💡 ${esc(m.hint)}</div>` : ''}
          <div class="row nowrap"><input id="at-in" class="grow" placeholder="Nazwa struktury ${idx + 1}…" autocomplete="off" autocapitalize="off" spellcheck="false">
          ${window.SpeechRecognition || window.webkitSpeechRecognition ? '<button data-act="atlas-mic">🎤</button>' : ''}</div>
          <div class="spacer"></div><div class="row nowrap">${m.hint && !AT.hint ? '<button data-act="atlas-hint">💡</button>' : ''}<button class="grow" data-act="atlas-skip">Nie wiem</button><button class="primary grow" data-act="atlas-check">Sprawdź</button></div>`}`;
  }
  // wskazywanie
  const answered = AT.tap != null;
  onMount(() => {
    if (answered) return;
    const box = $('#at-stage');
    box.addEventListener('pointerdown', e => {
      const r = box.getBoundingClientRect(), x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
      // trafienie = najbliższa pinezka to szukana struktura i jest blisko (≤ 8% szerokości)
      const dist = p => Math.hypot((p.x - x) * r.width, (p.y - y) * r.height) / r.width;
      const nearest = a.marks.reduce((b, p) => dist(p) < dist(b) ? p : b, a.marks[0]);
      const ok = nearest.id === m.id && dist(m) < 0.08;
      AT.tap = { x, y, ok }; AT.res.push({ id: m.id, ok, given: ok ? '' : (nearest.name || '?') }); render();
    });
  });
  return prog + `<div class="card center" style="margin-bottom:8px">Wskaż: <b style="font-size:20px">${esc(m.name)}</b></div>
    <div class="atlas-view"><div class="occl" id="at-stage" style="touch-action:none"><img src="${IMG[a.imageId] || ''}" alt="">
      ${answered ? `<div class="pin ${AT.tap.ok ? 'rev' : 'target'}" style="left:${m.x * 100}%;top:${m.y * 100}%">${idx + 1}</div>
        <div class="tapmark ${AT.tap.ok ? 'ok' : 'bad'}" style="left:${AT.tap.x * 100}%;top:${AT.tap.y * 100}%"></div>` : ''}</div></div>
    ${answered ? `<div class="center">${AT.tap.ok ? '✅ Dokładnie tu!' : '❌ Tutaj jest (czerwona pinezka)'}</div><div class="spacer"></div><button class="primary block" data-act="atlas-next">Dalej ›</button>` : '<p class="small muted center">Stuknij w obraz w miejscu tej struktury.</p>'}`;
}

Object.assign(ACTIONS, {
  'atlas-new': async el => {
    const id = await getImage(el.dataset.src); if (!id) return;
    const name = prompt('Nazwa ryciny (np. „Mięśnie kończyny górnej – przód”):', 'Rycina ' + ((S.atlases || []).length + 1)) || 'Rycina';
    const a = touch({ id: uid(), name: name.trim(), imageId: id, marks: [], created: Date.now() });
    S.atlases.push(a); save(); AT = null; go('#/atlas/' + a.id);
  },
  'atlas-back': () => { AT = null; go('#/atlas'); },
  'atlas-rename': el => { const a = atlasById(el.dataset.id); const n = prompt('Nazwa:', a.name); if (n?.trim()) { a.name = n.trim(); touch(a); save(); render(); } },
  'atlas-del': el => {
    const a = atlasById(el.dataset.id); if (!a || !confirm(`Usunąć rycinę „${a.name}”? Trafi do kosza (przywrócisz ją w Więcej → Bezpieczeństwo danych).`)) return;
    emit('deleting', 'atlas', { atlas: a });
    S.atlases = S.atlases.filter(x => x !== a); S.tomb[a.id] = Date.now(); save(); AT = null; toast('Rycina usunięta – jest w koszu'); go('#/atlas'); render();
  },
  'atlas-mode': el => { const a = atlasById(AT.id); AT.q = null; AT.saved = false; AT.mode = el.dataset.m; if (AT.mode === 'name' || AT.mode === 'point') startAtlasQuiz(a, AT.mode); render(); },
  'atlas-mark-del': el => { const a = atlasById(AT.id); a.marks = a.marks.filter(m => m.id !== el.dataset.id); touch(a); save(); render(); },
  'atlas-reveal': el => { AT.shown.has(el.dataset.id) ? AT.shown.delete(el.dataset.id) : AT.shown.add(el.dataset.id); render(); },
  'atlas-all': () => { const a = atlasById(AT.id); AT.shown = AT.shown.size === a.marks.length ? new Set() : new Set(a.marks.map(m => m.id)); render(); },
  'atlas-check': () => {
    const a = atlasById(AT.id), m = a.marks.find(x => x.id === AT.q[AT.i]), given = $('#at-in')?.value.trim() || '';
    const ok = checkAnswer(given, m.name) !== 'wrong'; AT.ans = { given, ok }; AT.res.push({ id: m.id, ok, given }); render();
  },
  'atlas-skip': () => { const m = AT.q[AT.i]; AT.ans = { given: '', ok: false }; AT.res.push({ id: m, ok: false, given: '' }); render(); },
  'atlas-override': () => { AT.ans.ok = true; AT.res[AT.res.length - 1].ok = true; render(); },
  'atlas-hint': () => { AT.hint = true; render(); },
  'atlas-next': () => { AT.i++; AT.ans = null; AT.tap = null; AT.hint = false; render(); },
  'atlas-again': () => { AT.saved = false; startAtlasQuiz(atlasById(AT.id), AT.mode); render(); },
  'atlas-wrong': () => { const wrong = AT.res.filter(r => !r.ok).map(r => r.id); AT.saved = true; AT.q = shuffle(wrong); AT.i = 0; AT.res = []; AT.ans = null; AT.tap = null; AT.t0 = Date.now(); render(); },
  'atlas-mic': () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition; if (!SR) return;
    const r = new SR(); r.lang = 'pl-PL'; r.maxAlternatives = 3;
    r.onresult = e => { const inp = $('#at-in'); if (inp) { inp.value = e.results[0][0].transcript; ACTIONS['atlas-check'](); } };
    r.onerror = e => toast('Mikrofon: ' + e.error); r.start(); toast('🎤 Mów…');
  },
  'atlas-cards': el => {
    const a = atlasById(el.dataset.id), marks = a.marks.filter(m => m.name.trim());
    if (!marks.length) return toast('Najpierw nadaj nazwy strukturom');
    const deck = S.decks.find(d => d.name === a.name) || newDeck(a.name);
    const fields = { type: 'occl', style: 'pin', imageId: a.imageId, hideAll: false, title: a.name, hint: '', extra: '', src: 'atlas-' + a.id,
      boxes: marks.map(m => ({ id: m.id, x: m.x, y: m.y, w: 0, h: 0, label: m.name.trim(), hint: (m.hint || '').trim() })) };
    const ex = S.notes.find(n => n.src === fields.src);
    if (ex) { Object.assign(ex, fields); touch(ex); syncCards(ex); } else addNote({ ...fields, deckId: deck.id });
    save(); toast(`Gotowe: ${marks.length} kart w talii „${ex ? deckById(ex.deckId)?.name : deck.name}”`, 3500);
  },
});

// ============================================================ Rysowanie z pamięci + porównanie z ryciną
var DRAW_COLORS = ['#111827', '#dc2626', '#2563eb', '#16a34a', '#f59e0b', '#9333ea'];
var GRADES = [[1, '😕', 'Słabo'], [2, '🙂', 'Nieźle'], [3, '🤩', 'Bardzo dobrze']];
function atlasDraw(a) {
  const D = AT.draw || (AT.draw = { strokes: [], color: DRAW_COLORS[0], size: 4, erase: false, ghost: false, compare: false, opacity: .5, side: false });
  const hist = (a.draws || []).slice().reverse();
  if (D.compare) {
    return `<p class="small muted">Przesuń suwak, żeby nałożyć rycinę na swój rysunek.${a.marks.length ? ' Pinezki pokazują nazwy struktur.' : ''}</p>
      <div class="seg" style="display:flex;margin-bottom:8px"><button class="grow ${D.side ? '' : 'on'}" data-act="draw-side" data-v="0">Nałożenie</button><button class="grow ${D.side ? 'on' : ''}" data-act="draw-side" data-v="1">Obok siebie</button></div>
      ${D.side ? `<div class="sidebyside"><figure><img src="${D.png}" alt=""><figcaption>Twój rysunek</figcaption></figure><figure><img src="${IMG[a.imageId]}" alt=""><figcaption>Rycina</figcaption></figure></div>`
        : `<div class="cmp"><img src="${D.png}" alt=""><img class="ref" src="${IMG[a.imageId]}" alt="" style="opacity:${D.opacity}">
          ${a.marks.map((m, i) => `<div class="pinlabel small-l" style="left:${m.x * 100}%;top:${m.y * 100}%;opacity:${D.opacity}">${i + 1}. ${esc(m.name)}</div>`).join('')}</div>
          <input type="range" min="0" max="1" step="0.02" value="${D.opacity}" id="cmp-op" aria-label="Przezroczystość ryciny">
          <div class="row small muted"><span class="grow">tylko rysunek</span><span>tylko rycina</span></div>`}
      <h3>Jak Ci poszło?</h3>
      <div class="row nowrap">${GRADES.map(([g, e, l]) => `<button class="grow grade-self" data-act="draw-grade" data-g="${g}"><span>${e}</span><small>${l}</small></button>`).join('')}</div>
      <div class="spacer"></div><button class="block" data-act="draw-back">✏️ Wróć do rysunku</button>`;
  }
  onMount(() => mountDraw(a));
  return `<p class="small muted">Narysuj z pamięci strukturę z tej ryciny, a potem porównaj.</p>
    <div class="drawtools">${DRAW_COLORS.map(c => `<button class="dcol${!D.erase && D.color === c ? ' on' : ''}" style="background:${c}" data-act="draw-color" data-c="${c}"></button>`).join('')}
      <select id="draw-size">${[[2, 'cienki'], [4, 'średni'], [8, 'gruby'], [16, 'marker']].map(([v, l]) => `<option value="${v}" ${D.size === v ? 'selected' : ''}>${l}</option>`).join('')}</select>
      <button class="sm${D.erase ? ' primary' : ''}" data-act="draw-erase">🧽</button><button class="sm" data-act="draw-undo">↶</button><button class="sm" data-act="draw-clear">🗑️</button></div>
    <label class="check small"><input type="checkbox" id="draw-ghost" ${D.ghost ? 'checked' : ''}> Kalka – pokaż słabo rycinę pod spodem (łatwiejszy trening)</label>
    <div class="drawwrap"><img class="ghost${D.ghost ? '' : ' hidden'}" src="${IMG[a.imageId]}" alt=""><canvas id="draw-cv"></canvas></div>
    <button class="primary block" data-act="draw-compare" style="min-height:54px">🔍 Porównaj z ryciną</button>
    ${hist.length ? `<h3>Twoje próby (${hist.length})</h3><div class="gallery">${hist.map(d => `<figure>${IMG[d.imageId] ? `<img src="${IMG[d.imageId]}" alt="">` : ''}<figcaption>${GRADES.find(g => g[0] === d.grade)?.[1] || ''} ${new Date(d.t).toLocaleDateString('pl')}</figcaption></figure>`).join('')}</div>` : ''}`;
}
function mountDraw(a) {
  const D = AT.draw, cv = $('#draw-cv'); if (!cv) return;
  const wrap = cv.parentElement, ctx = cv.getContext('2d'), dpr = devicePixelRatio || 1;
  const im = new Image();
  im.onload = () => {
    const w = wrap.clientWidth, h = Math.round(w * im.naturalHeight / im.naturalWidth);
    cv.style.width = w + 'px'; cv.style.height = h + 'px'; cv.width = w * dpr; cv.height = h * dpr; wrap.style.height = h + 'px';
    D.w = w; D.h = h; redraw();
  };
  im.src = IMG[a.imageId];
  function redraw() {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, D.w, D.h);
    for (const s of D.strokes) {
      ctx.globalCompositeOperation = s.erase ? 'destination-out' : 'source-over';
      ctx.strokeStyle = s.color; ctx.lineWidth = s.size; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      ctx.beginPath(); s.pts.forEach(([x, y], i) => i ? ctx.lineTo(x * D.w, y * D.h) : ctx.moveTo(x * D.w, y * D.h));
      if (s.pts.length === 1) ctx.lineTo(s.pts[0][0] * D.w + .1, s.pts[0][1] * D.h);
      ctx.stroke();
    }
    ctx.globalCompositeOperation = 'source-over';
  }
  D.redraw = redraw;
  let cur = null;
  const pos = e => { const r = cv.getBoundingClientRect(); return [clamp((e.clientX - r.left) / r.width, 0, 1), clamp((e.clientY - r.top) / r.height, 0, 1)]; };
  cv.addEventListener('pointerdown', e => { e.preventDefault(); cv.setPointerCapture(e.pointerId); cur = { color: D.color, size: D.erase ? D.size * 3 : D.size, erase: D.erase, pts: [pos(e)] }; D.strokes.push(cur); redraw(); });
  cv.addEventListener('pointermove', e => { if (!cur) return; cur.pts.push(pos(e)); redraw(); });
  const end = () => { cur = null; };
  cv.addEventListener('pointerup', end); cv.addEventListener('pointercancel', end);
  $('#draw-size').addEventListener('change', e => { D.size = +e.target.value; });
  $('#draw-ghost').addEventListener('change', e => { D.ghost = e.target.checked; $('.drawwrap .ghost').classList.toggle('hidden', !D.ghost); });
}
document.addEventListener('input', e => {
  if (e.target.id !== 'cmp-op' || !AT?.draw) return;
  AT.draw.opacity = +e.target.value;
  $$('.cmp .ref, .cmp .pinlabel').forEach(el => { el.style.opacity = AT.draw.opacity; });
});
function drawingPng() {
  // rysunek na białym tle (do porównania i zapisania)
  const D = AT.draw, src = $('#draw-cv'); const c = document.createElement('canvas'); c.width = src.width; c.height = src.height;
  const g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(src, 0, 0);
  return c.toDataURL('image/jpeg', .85);
}
Object.assign(ACTIONS, {
  'draw-color': el => { AT.draw.color = el.dataset.c; AT.draw.erase = false; $$('.dcol').forEach(b => b.classList.toggle('on', b.dataset.c === el.dataset.c)); $('[data-act=draw-erase]')?.classList.remove('primary'); },
  'draw-erase': el => { AT.draw.erase = !AT.draw.erase; el.classList.toggle('primary', AT.draw.erase); },
  'draw-undo': () => { AT.draw.strokes.pop(); AT.draw.redraw?.(); },
  'draw-clear': () => { if (AT.draw.strokes.length && confirm('Wyczyścić rysunek?')) { AT.draw.strokes = []; AT.draw.redraw?.(); } },
  'draw-compare': () => { if (!AT.draw.strokes.length) return toast('Najpierw coś narysuj ✏️'); AT.draw.png = drawingPng(); AT.draw.compare = true; render(); scrollTo(0, 0); },
  'draw-back': () => { AT.draw.compare = false; render(); },
  'draw-side': el => { AT.draw.side = el.dataset.v === '1'; render(); },
  'draw-grade': async el => {
    const a = atlasById(AT.id), id = await putImage(AT.draw.png);
    a.draws = [...(a.draws || []), { id: uid(), t: Date.now(), grade: +el.dataset.g, imageId: id }].slice(-12);
    touch(a); S.stats.drawings = (S.stats.drawings || 0) + 1; save();
    AT.draw = null; toast('Zapisano próbę ✓ – narysuj jeszcze raz za jakiś czas'); render();
  },
});
;

/* ===== reactions.js ===== */
'use strict';
/* Reakcje (GIF na ekranie): po wygranej bitwie, ukończeniu zestawu fiszek albo celu dziennego pokazuje się GIF.
   GIF-y zdobywa się WYŁĄCZNIE ze skrzynki z GIF-ami (ekwipunek 🎒) – nie da się wgrać własnego.
   Bez GIF-a z ekwipunku: GIF ustawiony przez hosta albo domyślny kot 🐈‍⬛.
   GIF „wygranej” widzą też przeciwnicy – po bitwie i w teleturnieju pokazuje się wszystkim graczom. */

var REACT_SLOTS = {
  win: { name: '🏆 Wygrana bitwa', caption: 'Wygrana! 🏆', def: true },
  session: { name: '✅ Ukończony zestaw fiszek', caption: 'Zestaw zrobiony! 🎉', def: true },
  goal: { name: '🎯 Cel dzienny osiągnięty', caption: 'Cel na dziś zaliczony! 🔥', def: false },
};
var REACT_DEFAULT = 'assets/e8/popper.webp';   // własna grafika 8-bit (bez memów z internetu)
var GLOBAL_RX = {};
var GIF_CASE = [];            // GIF-y do wylosowania w skrzynce (host wgrywa je w panelu) – [{ id, name, path, r, t }]
var GIFCASE_PREVIEW = {};   // podgląd świeżo wgranych (zanim GitHub Pages je opublikuje)
var gifById = id => GIF_CASE.find(g => g.id === id);
var gifSrcs = g => [GIFCASE_PREVIEW[g.id], g.path + '?v=' + (g.t || 0), rawUrl(g.path)].filter(Boolean);
var gifImg = (g, cls = '') => { const s = gifSrcs(g); return `<img class="${cls}" src="${esc(s[0])}" data-alt="${esc(JSON.stringify(s.slice(1)))}" alt="${esc(g.name || '')}" loading="lazy">`; };
// GIF z kolekcji ustawiony jako reakcja (jeśli nadal go masz)
var rxGif = k => { const id = S?.settings?.reactions?.[k]?.gid, g = id && gifById(id); return g && typeof hasItem === 'function' && hasItem('gif', id) ? g : null; };   // slot -> { path } – GIF-y ustawione przez hosta dla wszystkich (assets/global.json w repozytorium)
// kolejność: GIF z ekwipunku → GIF od hosta → domyślny kot
var GLOBAL_PREVIEW = {};   // podgląd od razu po wgraniu przez hosta (zanim GitHub Pages opublikuje plik)
var rxRepo = () => (typeof hostRepo === 'function' ? hostRepo() : 'OskarZio/aa');
var rawUrl = path => `https://raw.githubusercontent.com/${rxRepo()}/HEAD/${path}`;
// adresy GIF-a hosta: najpierw ze strony (GitHub Pages), a gdy się nie wczyta – prosto z repozytorium
var globalSrcs = k => GLOBAL_RX[k]?.path ? [GLOBAL_PREVIEW[k], GLOBAL_RX[k].path + '?v=' + (GLOBAL_RX[k].t || 0), rawUrl(GLOBAL_RX[k].path)].filter(Boolean) : [];
var rxSrcs = k => rxGif(k) ? [...gifSrcs(rxGif(k)), REACT_DEFAULT] : [...globalSrcs(k), REACT_DEFAULT];
var rxSrc = k => rxSrcs(k)[0];
var rxIsCat = k => !rxGif(k) && !GLOBAL_RX[k]?.path;
// <img> z listą zapasowych adresów (gdy pierwszy się nie wczyta, próbuje kolejnego)
function rxImg(k, cls = '') {
  const srcs = rxSrcs(k);
  return `<img class="${cls}${rxIsCat(k) ? ' rx-default' : ''}" src="${esc(srcs[0])}" data-alt="${esc(JSON.stringify(srcs.slice(1)))}" alt="">`;
}
// zapasowe adresy obrazków bez atrybutu onerror (zgodne z Content-Security-Policy)
document.addEventListener('error', e => { const t = e.target; if (t?.tagName === 'IMG' && t.dataset?.alt) rxFallback(t); }, true);
window.rxFallback = img => {
  const alt = JSON.parse(img.dataset.alt || '[]'); if (!alt.length) return;
  img.dataset.alt = JSON.stringify(alt.slice(1));
  if (alt[0] === REACT_DEFAULT) img.classList.add('rx-default');
  img.src = alt[0];
};
// 🔒 lista z pliku globalnego: tylko pliki z naszego folderu, bezpieczne id, znana rzadkość
var GIF_PATH_RE = /^assets\/(gifcase|global|reactions)\/[\w.-]+\.(gif|webp|png|jpe?g)$/i;
var cleanGifCase = list => (Array.isArray(list) ? list : []).filter(g => g && GIF_PATH_RE.test(g.path || '') && /^[\w-]{1,40}$/.test(g.id || ''))
  .map(g => ({ id: g.id, path: g.path, name: String(g.name || 'GIF').slice(0, 40), r: ['common', 'rare', 'epic', 'legendary'].includes(g.r) ? g.r : 'common', t: +g.t || 0 }));
var cleanGlobalRx = o => Object.fromEntries(Object.entries(o && typeof o === 'object' ? o : {}).filter(([k, v]) => /^[\w-]{1,24}$/.test(k) && GIF_PATH_RE.test(v?.path || '')).map(([k, v]) => [k, { path: v.path, name: String(v.name || '').slice(0, 60), t: +v.t || 0 }]));
async function loadGlobalReactions() {
  // pobieramy listę ze strony i z repozytorium naraz – wygrywa nowsza
  const get = url => fetch(url, { cache: 'no-store' }).then(r => r.ok ? r.json() : null).catch(() => null);
  const [a, b] = await Promise.all([get('assets/global.json?t=' + Date.now()), get(rawUrl('assets/global.json') + '?t=' + Date.now())]);
  const best = [a, b].filter(Boolean).sort((x, y) => (y.updated || 0) - (x.updated || 0))[0];
  if (best) { GLOBAL_RX = cleanGlobalRx(best.reactions); GIF_CASE = cleanGifCase(best.gifCase); if (typeof render === 'function' && ['shop', 'host', 'case', 'inv', 'chat', 'more'].includes(parseRoute().parts[0])) render(); }
}
on('start', loadGlobalReactions);

// sprzątanie po dawnych, własnoręcznie wgranych GIF-ach (już nieobsługiwane)
on('start', () => { for (const k of Object.keys(REACT_SLOTS)) DB.del('gif:' + k).catch(() => {}); });
var reactCfg = () => (S.settings.reactions = S.settings.reactions || {});
var reactOn = k => (reactCfg()[k]?.on ?? REACT_SLOTS[k].def);

function showReaction(k, test) { return;   // 🎞️ reakcje GIF usunięte

  if (!test && !reactOn(k)) return;
  const cfg = reactCfg()[k] || {};
  rxOverlay(rxImg(k), esc(REACT_SLOTS[k].caption), cfg.dur);
}
// mój GIF wygranej (id z ekwipunku) – wysyłany innym graczom, żeby zobaczyli go, gdy wygram
var myWinGif = () => (reactOn('win') && rxGif('win')?.id) || null;
// GIF zwycięzcy na ekranie wszystkich graczy (gid z jego ekwipunku; nieznany / brak = domyślny)
function showWinnerGif(gid, name) {
  const g = gid && gifById(gid);
  const img = g ? gifImg(g) : `<img class="rx-default" src="${REACT_DEFAULT}" alt="">`;
  rxOverlay(img, `🏆 ${esc(name || 'Zwycięzca')} wygrywa!`, 4);
}
function rxOverlay(imgHTML, caption, dur) {
  document.querySelector('.reaction')?.remove();
  const el = document.createElement('div'); el.className = 'reaction';
  el.innerHTML = `<div class="rx-card">${imgHTML}<b>${caption}</b><small>stuknij, aby zamknąć</small></div>`;
  const close = () => { el.classList.add('out'); setTimeout(() => el.remove(), 300); };
  el.addEventListener('click', close);
  document.body.append(el);
  setTimeout(close, (dur || 3.5) * 1000);
}
on('battleWin', () => setTimeout(() => showReaction('win'), 400));
on('sessionEnd', s => { if (s.done > 0) setTimeout(() => showReaction('session'), 250); });
on('goal', () => setTimeout(() => showReaction('goal'), 600));

function reactionsSectionHTML() { return '';   // 🎞️ reakcje GIF usunięte

  const cfg = reactCfg();
  return `<div class="card"><h2 style="margin-top:0">🎬 Reakcje (GIF)</h2>
    <p class="small muted">Po wybranym zdarzeniu na ekranie pokaże się GIF. GIF-y zdobywasz tylko w 🎞️ skrzynce z GIF-ami i ustawiasz w 🎒 Ekwipunku. Twój GIF wygranej widzą też przeciwnicy.</p>
    ${Object.entries(REACT_SLOTS).map(([k, sl]) => { const c = cfg[k] || {}, g = rxGif(k);
      const note = g ? `<br><small class="muted">z ekwipunku: ${esc(g.name || 'GIF')}</small>` : GLOBAL_RX[k]?.path ? '<br><small class="muted">GIF od hosta</small>' : '<br><small class="muted">domyślny kot</small>';
      return `<div class="sndrow"><div class="row nowrap">${rxImg(k, 'rx-thumb')}<b class="grow">${sl.name}${note}</b>
          <label class="switch"><input type="checkbox" data-rx-on="${k}" ${reactOn(k) ? 'checked' : ''}><span></span></label></div>
        <div class="row nowrap"><button class="sm" data-act="rx-test" data-k="${k}">▶ Pokaż</button>
          <button class="sm" data-go="#/inv">🎒 Zmień w ekwipunku</button>
          <select data-rx-dur="${k}" style="width:auto;margin-left:auto">${[2, 3.5, 5, 8].map(d => `<option value="${d}" ${(c.dur || 3.5) === d ? 'selected' : ''}>${d} s</option>`).join('')}</select></div></div>`; }).join('')}
  </div>`;
}
document.addEventListener('change', e => {
  const on1 = e.target.dataset?.rxOn, dur = e.target.dataset?.rxDur, cfg = reactCfg();
  if (on1) { cfg[on1] = { ...(cfg[on1] || {}), on: e.target.checked }; save(); }
  if (dur) { cfg[dur] = { ...(cfg[dur] || {}), dur: +e.target.value }; save(); }
});
Object.assign(ACTIONS, {
  'rx-test': el => showReaction(el.dataset.k, true),
});
;

/* ===== host.js ===== */
'use strict';
/* Panel hosta: narzędzia właściciela aplikacji (konfiguracja, statystyki, testy).
   Plik trafia do repozytorium na GitHubie (assets/global/…) razem z listą assets/global.json – GitHub Pages
   udostępnia je każdemu, a aplikacja wczytuje przy starcie. Zapis wymaga tokenu GitHub z prawem zapisu do repozytorium,
   więc nawet ktoś, kto pozna kod, nie podmieni plików bez tokenu właściciela. */

var HOST_HASH = 'c445ae5875d6a31cad713ed08ef1597bb31c4a818192671d1bc6774d80424209';   // SHA-256 kodu hosta
var sha256 = async t => [...new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(t)))].map(b => b.toString(16).padStart(2, '0')).join('');
// 🔒 kod sam nie wystarczy (da się go obejść w przeglądarce) – panel otwiera się tylko kontu właściciela potwierdzonemu przez serwer
var hostUnlocked = () => { try { return localStorage.getItem('hostOK') === HOST_HASH && typeof IS_ADMIN !== 'undefined' && IS_ADMIN === true; } catch { return false; } };
function hostRepo() {
  if (S.settings.hostRepo) return S.settings.hostRepo;
  if (location.hostname.endsWith('.github.io')) { const o = location.hostname.split('.')[0], r = location.pathname.split('/')[1]; return `${o}/${r || o + '.github.io'}`; }
  return 'OskarZio/aa';
}
async function ghRepo(path, opt = {}) {
  const r = await fetch(`https://api.github.com/repos/${hostRepo()}/contents/${path}`, {
    ...opt, headers: { Authorization: 'Bearer ' + S.settings.hostToken, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' } });
  if (r.status === 404 && (!opt.method || opt.method === 'GET')) return null;
  if (!r.ok) {
    const msg = (await r.json().catch(() => ({}))).message || '';
    throw new Error(r.status === 401 ? 'zły token (GitHub go nie rozpoznaje)' : r.status === 403 || r.status === 404 ? `token nie ma prawa zapisu do ${hostRepo()}${msg ? ' – ' + msg : ''}` : `GitHub ${r.status}${msg ? ' – ' + msg : ''}`);
  }
  return r.json();
}
// token i repozytorium bierzemy też prosto z pól (na iPhonie „change” przychodzi dopiero po opuszczeniu pola)
function syncHostFields() {
  const t = $('#host-token'), r = $('#host-repo');
  if (t) S.settings.hostToken = t.value.trim().replace(/\s+/g, '');
  if (r && r.value.trim()) S.settings.hostRepo = r.value.trim().replace(/^https?:\/\/github\.com\//, '').replace(/\/$/, '');
  save();
}
var HOST_CHECK = null;   // wyniki sprawdzania tokenu
async function checkHostToken() {
  syncHostFields();
  const tok = S.settings.hostToken, repo = hostRepo(), res = [];
  const step = (ok, text) => { res.push({ ok, text }); HOST_CHECK = { res: [...res], running: true }; render(); };
  HOST_CHECK = { res: [], running: true }; render();
  const H = { Authorization: 'Bearer ' + tok, Accept: 'application/vnd.github+json' };
  try {
    if (!tok) return step(false, 'Pole tokenu jest puste – wklej token.');
    if (!/^(github_pat_|ghp_)/.test(tok)) step(false, 'Token zwykle zaczyna się od „github_pat_” albo „ghp_” – sprawdź, czy skopiowałeś cały.');
    let r = await fetch('https://api.github.com/user', { headers: H });
    if (r.status === 401) return step(false, '1. Token jest nieprawidłowy lub wygasł – wygeneruj nowy i wklej ponownie.');
    const user = await r.json();
    step(r.ok, r.ok ? `1. Token działa – konto: ${user.login}` : `1. Błąd GitHub ${r.status}`);
    r = await fetch(`https://api.github.com/repos/${repo}`, { headers: H });
    if (!r.ok) return step(false, `2. Token nie widzi repozytorium „${repo}”. W ustawieniach tokenu wybierz „Only select repositories” → ${repo.split('/')[1]}.`);
    const rp = await r.json();
    step(true, `2. Repozytorium widoczne: ${rp.full_name}${rp.private ? ' (prywatne)' : ''}, gałąź: ${rp.default_branch}`);
    // jedyny pewny test zapisu: zapisanie małego pliku kontrolnego
    const path = 'assets/global/.sprawdzenie.txt';
    r = await fetch(`https://api.github.com/repos/${repo}/contents/${path}`, { headers: H });
    const sha = r.ok ? (await r.json()).sha : undefined;
    r = await fetch(`https://api.github.com/repos/${repo}/contents/${path}`, { method: 'PUT', headers: { ...H, 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: 'Sprawdzenie tokenu hosta', content: btoa('ok ' + new Date().toISOString()), ...(sha ? { sha } : {}) }) });
    if (!r.ok) {
      const msg = (await r.json().catch(() => ({}))).message || '';
      return step(false, `3. Brak prawa zapisu (${r.status}${msg ? ': ' + msg : ''}). W tokenie ustaw Repository permissions → Contents: „Read and write”.`);
    }
    step(true, '3. Zapis działa ✓ – panel może zapisywać ustawienia dla wszystkich.');
  } catch (e) { step(false, 'Brak połączenia z GitHub: ' + e.message); }
  finally { HOST_CHECK.running = false; render(); }
}
var b64utf8 = s => btoa(unescape(encodeURIComponent(s)));
var utf8b64 = s => decodeURIComponent(escape(atob(s.replace(/\n/g, ''))));
async function readGlobalJson() {
  const f = await ghRepo('assets/global.json');
  return f ? { sha: f.sha, data: JSON.parse(utf8b64(f.content)) } : { sha: null, data: { v: 1, reactions: {} } };
}
async function writeGlobalJson(data, sha, msg) {
  data.updated = Date.now();
  await ghRepo('assets/global.json', { method: 'PUT', body: JSON.stringify({ message: msg, content: b64utf8(JSON.stringify(data, null, 2)), ...(sha ? { sha } : {}) }) });
}

