    const ok = Math.random() < p.acc, wrongs = q.opts.map((_, k) => k).filter(k => q.opts[k] !== q.a);
    const k = ok ? q.opts.indexOf(q.a) : pick(wrongs), ms = Math.min(R.sec * 1000 - 300, (1400 + Math.random() * 5200) * p.fast);
    later(() => showTakeAnswer(p, k, ms), ms);
