        <div class="row nowrap"><input id="sh-pin" class="grow sh-pin-in" inputmode="numeric" maxlength="6" placeholder="PIN" value="${esc(q?.get('pin') || '')}"><button class="primary" data-act="show-join">Dołącz</button></div></div>
