    <div class="time-kpis">${[['wyklute', ok.length], ['skupienie', fmtDur(mins * 60000)], ['rzadkie+', rare], ['pęknięte', list.length - ok.length]].map(([l, v]) => `<div><b>${v}</b><small>${l}</small></div>`).join('')}</div>
