var pageOpen = (p, l = heroLine()) => p === 0 || pageDone(p - 1, l);
var treeDone = (l = heroLine()) => pageDone(2, l);
var lineTier = (h = hero(), l = heroLine(h)) => ((h.skt = h.skt || {})[l] = h.skt[l] || {});
function skVal(eff) {
  const L = lineDef(), own = lineSk(), tier = lineTier();
  let v = L.passive[2][eff] || 0;
  for (const n of allNodes()) if (own[n.id] && n.eff === eff) v += n.v * (1 + .5 * (tier[n.id] || 0));
  return v * heroTierMul(heroLine());
}
var hasSk = eff => skVal(eff) > 0;
// 🌳 punkty umiejętności osobno dla każdej postaci: zdobywa je ta postać, którą grasz, gdy bohater awansuje (1 na start)
function linePts(l = heroLine()) {
  const h = hero();
  if (!h.spl) h.spl = { [heroLine(h)]: heroLv() + (h.pr || 0) };   // przejście ze wspólnych punktów: dotychczasowe dostaje postać, którą grasz
  if (h.spl[l] == null) h.spl[l] = Math.max(1, Object.keys(h.sk[l] || {}).length);
  return h.spl[l];
}
var skSpent = (l = heroLine()) => Object.keys(lineSk(hero(), l)).length + Object.values(lineTier(hero(), l)).reduce((a, t) => a + t, 0);
var skPoints = (l = heroLine()) => linePts(l) - skSpent(l);

// ---------- ⏱️ boostery: 30 min; w weekend „Podwójne XP” za darmo, co 3 dni darmowy booster do odebrania
var BOOSTS = { xp2: { name: 'Podwójne XP', desc: 'doświadczenie bohatera ×2', img: 'b_star', price: 150 }, gems2: { name: 'Podwójne kryształy', desc: '🪙 z bossów i łupów ×2', img: 'b_gstar', price: 200 }, loot2: { name: 'Szczęście łupieżcy', desc: '+1 przedmiot w każdej skrzyni', img: 'b_swords', price: 200 } };
var BOOST_MS = 30 * 60000;
var isWeekend = () => [0, 6].includes(new Date().getDay());
var boostOn = k => (k === 'xp2' && isWeekend()) || (hero().boost?.[k] || 0) > Date.now();
var boostLeft = k => Math.max(0, (hero().boost?.[k] || 0) - Date.now());
var gemMul = () => boostOn('gems2') ? 2 : 1;
var xpMul = () => (boostOn('xp2') ? 2 : 1) * (1 + skVal('xp') / 100) * (1 + .1 * (hero().pr || 0));
function activateBoost(k) {
  if (itemCount('boost', k) < 1) return;
  const h = hero(); h.boost = h.boost || {}; addItem('boost', k, -1);
  h.boost[k] = Math.max(Date.now(), h.boost[k] || 0) + BOOST_MS; h.mod = Date.now(); save();
  toast(`⏱️ ${BOOSTS[k].name} aktywne przez ${Math.round(boostLeft(k) / 60000)} min`); render();
}
var boostChips = () => [isWeekend() ? '<span class="boost-chip">🎉 Weekend: podwójne XP</span>' : '',
  ...Object.keys(BOOSTS).filter(k => boostLeft(k) > 0).map(k => `<span class="boost-chip">${BOOSTS[k].name} · ${Math.ceil(boostLeft(k) / 60000)} min</span>`)].join('');
var FREE_BOOST_DAYS = 3;
var freeBoostKey = () => 'freeboost-' + Math.floor(Date.now() / (FREE_BOOST_DAYS * DAY));
var freeBoostReady = () => !S.items.some(i => i.id === freeBoostKey());
function claimFreeBoost() {
  if (!freeBoostReady()) return;
  const ks = Object.keys(BOOSTS), k = ks[Math.random() * ks.length | 0];
  addItem('boost', k, 1, freeBoostKey()); toast(`🎁 Darmowy booster: ${BOOSTS[k].name} – włącz, kiedy chcesz`); render();
}

// ---------- ❤️ serca: przegrana walka zabiera serce; 1 serce wraca co 2 h albo za 15 powtórek nauki
var LIVES_MAX = 3, LIFE_MS = 2 * HOUR, LIFE_REV = 15;
function lives() {
  const L = hero().lives;
  if (L.n >= LIVES_MAX) { L.t = Date.now(); return L; }
  const k = Math.floor((Date.now() - L.t) / LIFE_MS); if (k > 0) { L.n = Math.min(LIVES_MAX, L.n + k); L.t += k * LIFE_MS; }
  return L;
}
