  a_kimono: GR('a', 'Kimono mistrza', 'epic', 'g_kimono', { hp: 30, dodge: 8, def: 6 }), a_ring: GR('a', 'Pierścień pamięci', 'epic', 'g_ring', { hp: 35, def: 12 }),
