var duoVoteWinner = C => { const P = Object.values(C.vote?.picks || {}); if (!P.length) return null; const n = {}; for (const k of P) n[k] = (n[k] || 0) + 1; const top = Math.max(...Object.values(n)), best = Object.keys(n).filter(k => n[k] === top); return best[Math.random() * best.length | 0]; };
