    const f = T.floor, xp = Math.round((B.ok * 3 + 30 + 15 * f) * (TW_GK ? 1 : 2) * xpMul()), gems = Math.round(Math.min(TW_GK ? 20 : 40, TW_GK ? 2 + .75 * f : 4 + 1.5 * f) * gemMul());   // ⚖️ wolniej rosnące, z limitem na piętro   // wieża wiedzy (quiz): mniej 🪙
