ROUTES.boss = (...a) => { const v = twMap0(...a); if (!v?.html || v.focus) return v; return { ...v, html: v.html.replace('<h2 class="bm-h">📚 Twoje talie', towerCardHTML() + '<h2 class="bm-h">📚 Twoje talie') }; };
