  const wrong = (key, ans, pool) => { const r = rng(h32(key)), p = [...new Set(pool.filter(x => x !== ans))], w = [];
    while (w.length < 3 && p.length) w.push(p.splice(Math.floor(r() * p.length), 1)[0]); return w; };
