var QL_HINT_FIX = {"w Quizlecie: „Adjust a footstraps” (literówka)": "Błąd w Quizlecie: „Adjust a footstraps”. Rodzajnik „a” (= jeden) nie stoi przed liczbą mnogą – footstraps to wiele pasków, więc „the footstraps”.", "w Quizlecie: „Grap the handle” (literówka)": "Błąd w Quizlecie: „Grap”. Takiego słowa nie ma – chwytać = grab. Skojarzenie: grab ≈ grabie, którymi chwytasz liście.", "w Quizlecie: „Joins” (literówka)": "Błąd w Quizlecie: „Joins”. Join = łączyć, dołączać. Staw to joint – z „t” na końcu (stawy = joints).", "w Quizlecie: „Chichen pox” (literówka)": "Błąd w Quizlecie: „Chichen pox”. Kurczak = chicken, ospa wietrzna = chickenpox (pisane razem).", "w Quizlecie było „Menrally handicapped” – to znaczy co innego (niepełnosprawny umysłowo); ruchowa = physically disabled": "W Quizlecie było „Mentally handicapped” – to znaczy niepełnosprawny umysłowo. Niepełnosprawność ruchowa = physically disabled.", "w Quizlecie: „rouing” (literówka)": "Błąd w Quizlecie: „rouing” – to zapis wymowy. Wiosłować = row [czyt. rou], wioślarstwo = rowing.", "w Quizlecie było „Recoverment” – takiego słowa nie ma": "Błąd w Quizlecie: „Recoverment” – takiego słowa nie ma. Recover = wyzdrowieć, recovery = wyzdrowienie.", "w Quizlecie było „Cycle” (= jeździć na rowerze); kolarstwo jako sport = cycling": "W Quizlecie było „Cycle” – to czasownik (jeździć na rowerze). Kolarstwo jako sport = cycling.", "w Quizlecie: „Achivemnet” (literówka)": "Błąd w Quizlecie: „Achivemnet” – przestawione litery. Achieve (osiągnąć) + -ment = achievement.", "w Quizlecie: „lin on your back” (literówka)": "Błąd w Quizlecie: „lin”. Lie = leżeć / połóż się. Nie myl z lay (= kłaść coś).", "w Quizlecie: „bent your knees” (literówka)": "Błąd w Quizlecie: „bent”. Polecenie to bend (zegnij); bent to forma przeszła – „knees bent” = ze zgiętymi kolanami."};
