for (const [l, m] of Object.entries(ABIL8)) { const L = LINES[l]; if (!L) continue;
  L.passive[0] = `${abTok(l, m[0])} ${stripEmo(L.passive[0])}`; L.ult[0] = `${abTok(l, m[1])} ${stripEmo(L.ult[0])}`;
  L.tree.forEach((b, i) => { b[0] = `${abTok(l, m[2 + i])} ${stripEmo(b[0])}`; }); }
